local config = {
  ui_story_5061_50610101_1_dialog_content = "Investigation Log, Entry 154.",
  ui_story_5061_50610101_2_dialog_content = "September 27, 22:00. Snowing.",
  ui_story_5061_50610101_3_dialog_content = "After traveling into the furthest reaches of Northland, I am currently approaching the site of the century-old <color=#FFB400>Aurorastorm</color>.",
  ui_story_5061_50610101_4_dialog_content = "This was a rare recorded Aurora-related anomaly event in Northland's history, and the Spirit of the Aurora's legend has endured for a long time since.",
  ui_story_5061_50610101_5_dialog_content = "Aurorians are born relying on Lumina, and the Aurora only appears when compact Lumina meets certain conditions in a given environment.",
  ui_story_5061_50610101_6_dialog_content = "It's an extreme manifestation of raw energy... perhaps the purest form of Lumina!",
  ui_story_5061_50610101_7_dialog_content = "It calls out to all Aurorians like a beacon in the night, serving as a symbol of their existence.",
  ui_story_5061_50610101_8_dialog_content = "Naturally, a rare phenomenon such as this is bound to attract people's awe and curiosity... And I'm no different!",
  ui_story_5061_50610101_9_dialog_content = "There are plenty of theories concerning the origins of the Aurora. The Dark Zone Turbulence theory, the Holy Light theory, the Polar Fragmentation theory, the Electromagnetic Storm theory...",
  ui_story_5061_50610101_10_dialog_content = "But personally, I believe the most plausible is the Ancient Power Source theory.",
  ui_story_5061_50610101_11_dialog_content = "The Aurora possesses an inconceivable amount of power, one that was most likely harnessed by the ancient civilizations hidden just beneath our feet.",
  ui_story_5061_50610101_12_dialog_content = "Lumopolis texts indicate that the very first Aurora emerged from a set of ancient ruins. The specific ruins themselves, however, are widely debated.",
  ui_story_5061_50610101_13_dialog_content = "If this hypothesis is correct, will I find the true origin of the Aurora at the end of my excursion?",
  ui_story_5061_50610101_14_dialog_content = "...",
  ui_story_5061_50610101_15_dialog_content = "It's now 22:14. I believe I'm now beyond Northland's borders, as well as the Beacon's protective range.",
  ui_story_5061_50610101_16_dialog_content = "I see a number of dark figures standing upright on the frozen plains. Perhaps the remnants of ancient trees, or possibly...",
  ui_story_5061_50610101_17_dialog_content = "...",
  ui_story_5061_50610101_18_dialog_content = "To avoid Eclipsite detection, I'll now shut off the recording device.",
  ui_story_5061_50610101_19_dialog_content = "If anyone discovers this recording, it means my luck took a turn for the worst. Should that happen, please deliver this to the Northland Court.",
  ui_story_5061_50610101_20_dialog_content = "I sincerely hope that future generations will find my research useful in uncovering the origins of the Aurora.",
  ui_story_5061_50610101_21_dialog_content = "So that one day, we may finally understand...",
  ui_story_5061_50610101_22_dialog_content = "Where Aurorians came from, and what kind of world we live in.",
  ui_story_5061_50610101_23_dialog_content = "... Ah! Is that—?!",
  ui_story_5061_50610101_24_dialog_content = "In the ice, is that... a person?!",
  ui_story_5061_50610101_25_dialog_content = "... A stranded traveler? Or maybe... Could this be the legendary Spirit of the Aurora?",
  ui_story_5061_50610101_26_dialog_content = "... Is she still alive?",
  ui_story_5061_50610201_1_dialog_content = "(Panting) I finally made it!",
  ui_story_5061_50610201_2_dialog_content = "The snow's only getting heavier! I gotta get back inside the Colossus!",
  ui_story_5061_50610201_3_dialog_content = "Just rub your hands together and breathe into them...",
  ui_story_5061_50610201_4_dialog_content = "Haaah—Haaaaah—",
  ui_story_5061_50610201_5_dialog_content = "It's no good! Even when I do that, my hands are still freezing!",
  ui_story_5061_50610201_6_dialog_content = "Haha, well you ARE in Northland, after all...",
  ui_story_5061_50610201_7_dialog_content = "If I knew it was gonna be this cold, I would've brought more winter survival gear for the job!",
  ui_story_5061_50610201_8_dialog_content = "Indeed, if Carleen was around, she definitely would've reminded you.",
  ui_story_5061_50610201_9_dialog_content = "In fact, she probably would've made you a nice, warm cup of tea by now!",
  ui_story_5061_50610201_10_dialog_content = "(Sighs) I already miss being back in Lumopolis and Illumina with everyone! At least I wouldn't be freezing to death.",
  ui_story_5061_50610201_11_dialog_content = "I'm sorry we weren't able to go with you this time...",
  ui_story_5061_50610201_12_dialog_content = "But I promise we'll have lots of fun in Northland together next time!",
  ui_story_5061_50610201_13_dialog_content = "And if Carleen comes along, she might even take us on a carriage ride!",
  ui_story_5061_50610201_14_dialog_content = "(If there's ever a next time, I'd rather stay in my Colossus...)",
  ui_story_5061_50610201_15_dialog_content = "It's fine, really. I'm just a little bored out here, and I can't think of anything else to talk about.",
  ui_story_5061_50610201_16_dialog_content = "I know. It's easy to feel lonely when you're traveling through the snow on your own. Why don't you try out the new communicator Officer Gronru gave you?",
  ui_story_5061_50610201_17_dialog_content = "It picks up all kinds of sounds and signals from across the world. Even if you're all alone on the Colossus, I'm sure it'll help lighten the mood for you!",
  ui_story_5061_50610201_18_dialog_content = "You might be able to hear the sound of machinery from Illumina, or even a music broadcast from Umbraton! Sounds incredible, right?",
  ui_story_5061_50610201_19_dialog_content = "... It'd be a lot more incredible if I could actually pick what to listen to...",
  ui_story_5061_50610201_20_dialog_content = "Guess you'll just have to have faith in Officer Gronru!",
  ui_story_5061_50610201_21_dialog_content = "Make sure to take good care of yourself out there. And if you see anything interesting, remember to tell us about it so we can see it together someday!",
  ui_story_5061_50610201_22_dialog_content = "Anyways, as long as Queen Bethlehem is around, Northland should be perfectly safe. Otherwise I'd never have been okay leaving you on your own!",
  ui_story_5061_50610201_23_dialog_content = "Well, training's about to start, so I should get going. Talk to you soon!",
  ui_story_5061_50610201_24_dialog_content = "Okay.",
  ui_story_5061_50610201_25_dialog_content = "...",
  ui_story_5061_50610201_26_dialog_content = "Because the time and place are wrong?",
  ui_story_5061_50610201_26X1_dialog_content = "Northland really is... Exactly how Carleen and the others describe it...",
  ui_story_5061_50610201_27_dialog_content = "The Northland today no longer resembles the enchanting fairytale that Carleen once described to me...",
  ui_story_5061_50610201_27X1_dialog_content = "It's completely different from places like Lumopolis and the Undercities.",
  ui_story_5061_50610201_28_dialog_content = "<color=#e8d9bb>Vast, cold, and mysterious, forests stretch on endlessly while mountain peaks stand tall, grandiose and majestic.</color>",
  ui_story_5061_50610201_29_dialog_content = "<color=#e8d9bb>There are scant traces of civilization left on this land, as if nothing has ever changed through the passing of thousands of years.</color>",
  ui_story_5061_50610201_30_dialog_content = "It's so quiet here...",
  ui_story_5061_50610201_31_dialog_content = "... Maybe I should try out Gronru's communicator. Anything to break this heavy silence.",
  ui_story_5061_50610201_32_option_content = "Activate Communicator",
  ui_story_5061_50610201_33_dialog_content = "(Click) Buzz, buzz...",
  ui_story_5061_50610201_34_dialog_content = "Buzz, buzz...",
  ui_story_5061_50610201_35_dialog_content = "... It's not working at all!",
  ui_story_5061_50610201_36_dialog_content = "All this static's giving me a headache. Guess I'll just shut it off...",
  ui_story_5061_50610201_37_dialog_content = "... A... Anyone?!",
  ui_story_5061_50610201_38_dialog_content = "... This is... the... Requesting help!",
  ui_story_5061_50610201_39_dialog_content = "Huh? A distress call?!",
  ui_story_5061_50610201_40_dialog_content = "I repeat: This is the northeast ridge of Cedar Peak on the border of Northland, at an elevation of 3,200 meters.",
  ui_story_5061_50610201_41_dialog_content = "I found someone trapped in the ice. Things look dire, and I'm unable to perform a rescue.",
  ui_story_5061_50610201_42_dialog_content = "Anyone who may be listening, please come equipped with ice-breaking tools and heating gear for the rescue!",
  ui_story_5061_50610201_43_dialog_content = "Cedar Peak... That's not far from here at all!",
  ui_story_5061_50610201_44_dialog_content = "Just hang on! Help is on the way!",
  ui_story_5061_50610201_45_dialog_content = "(The weather and terrain made it difficult to land quickly... I just hope I'm not too late.)",
  ui_story_5061_50610201_46_dialog_content = "Hello? Is anyone there? I picked up a distress call from this location!",
  ui_story_5061_50610201_47_dialog_content = "Hey! Can anyone hear me?! Guess I'll have to use my powers... Force Boo—Whoa!",
  ui_story_5061_50610201_48_dialog_content = "(The snow's so deep! And there's nothing but more snow in sight... Could they be buried somewhere under all of it?!)",
  ui_story_5061_50610201_49_dialog_content = "<color=#e8d9bb>Crunch—</color>",
  ui_story_5061_50610201_50_dialog_content = "What was that?",
  ui_story_5061_50610201_51_dialog_content = "<color=#e8d9bb>Crackling—</color>",
  ui_story_5061_50610201_52_dialog_content = "Ha...",
  ui_story_5061_50610201_53_dialog_content = "What is that sound... Could someone actually be buried in the snow?!",
  ui_story_5061_50610201_54_dialog_content = "Just hang on, I'll get you out of there!!",
  ui_story_5061_50610201_55_dialog_content = "Haah... Haah...",
  ui_story_5061_50610201_56_dialog_content = "Roaaar—",
  ui_story_5061_50610201_57_dialog_content = "Huh?!?!",
  ui_story_5061_50610201_58_dialog_content = "Activating emergency technique!",
  ui_story_5061_50610201_59_dialog_content = "Gaaah!",
  ui_story_5061_50610201_60_dialog_content = "Get behind me! I'll deal with this thing!",
  ui_story_5061_50610202_1_dialog_content = "Growl...",
  ui_story_5061_50610202_2_dialog_content = "Phew, I'm saved. Thank you...",
  ui_story_5061_50610202_3_dialog_content = "Excuse me, but you must be...",
  ui_story_5061_50610202_4_dialog_content = "Colors! I saw Lumina in all kinds of colors during our battle just now! They were as clear as day!",
  ui_story_5061_50610202_5_dialog_content = "It was like the path to victory appeared in my mind... I knew exactly what I had to do!",
  ui_story_5061_50610202_6_dialog_content = "I moved with the flow of Lumina like a leaf in the wind. Everything felt so natural...",
  ui_story_5061_50610202_7_dialog_content = "But how? How could that be?! I have to know more about it! I have to!!!",
  ui_story_5061_50610202_8_dialog_content = "You must be the Caelestite I've been hearing about lately! Would you mind answering a few of my questions? I'd love to learn more about your abilities, and about your experiences piloting the Colossus!",
  ui_story_5061_50610202_9_dialog_content = "H-Hang on a second! I'd be happy to talk, but shouldn't we at least introduce ourselves? My name's PlayerName.",
  ui_story_5061_50610202_10_dialog_content = "Oh! S-Sorry about that, I tend to get a little excited sometimes... It's a bad habit of mine, but I hope I didn't put you off or anything?",
  ui_story_5061_50610202_11_dialog_content = "My name is Antony, and I'm a folk scholar. Did you come because of the distress call I sent out?",
  ui_story_5061_50610202_12_dialog_content = "The weather's so extreme here that I got buried in the snow. All I could do was sit around and wait until I heard help approaching...",
  ui_story_5061_50610202_13_dialog_content = "Thank goodness I managed to hear you arrive!",
  ui_story_5061_50610202_14_dialog_content = "That's right. I'm not exactly built for this kind of environment either. I couldn't sense anyone out here, thought I was rescuing a person, which turned out to be an Eclipsite...",
  ui_story_5061_50610202_15_dialog_content = "Anyway, you mentioned something about a trapped person too, didn't you?",
  ui_story_5061_50610202_16_dialog_content = "It's true! But the situation is... a little hard to believe. It's completely different from what I originally thought...",
  ui_story_5061_50610202_17_dialog_content = "Here, come with me.",
  ui_story_5061_50610202_18_dialog_content = "Oh, and watch out for those icicles. Some of them have Eclipsites trapped inside.",
  ui_story_5061_50610202_19_dialog_content = "But there are tons of them...",
  ui_story_5061_50610202_20_dialog_content = "Here she is. Go on, take a look in the ice.",
  ui_story_5061_50610202_21_dialog_content = "Is that... a girl, inside the ice?",
  ui_story_5061_50610202_22_dialog_content = "... She's still alive?!",
  ui_story_5061_50610202_23_dialog_content = "I believe so, yes.",
  ui_story_5061_50610202_24_dialog_content = "Despite being trapped in the ice, her body shows no visible signs of having been frozen to death.",
  ui_story_5061_50610202_25_dialog_content = "In fact, it looks as if she's merely sleeping. As if this frozen tomb was no different than a bed...",
  ui_story_5061_50610202_26_dialog_content = "Maybe I can connect with her telepathically!",
  ui_story_5061_50610202_27_option_content = "Force Boost",
  ui_story_5061_50610202_28_dialog_content = "Nngh... Huh...?",
  ui_story_5061_50610202_29_dialog_content = "When did I... fall asleep...?",
  ui_story_5061_50610202_30_dialog_content = "How did this happen? I had... something important to do...",
  ui_story_5061_50610202_31_dialog_content = "If I fail... All of the nearby villages, no, all of Northland... My sister!!!",
  ui_story_5061_50610202_32_dialog_content = "She really is alive! And her mind is responding really intensely too!",
  ui_story_5061_50610202_33_dialog_content = "That's wonderful! Should we try breaking her out of the ice? Or maybe our best bet is to melt it first...",
  ui_story_5061_50610202_34_dialog_content = "Wait, I'm sensing some strange energy fluctuations nearby...",
  ui_story_5061_50610202_35_dialog_content = "And it looks like she's the source of it. She must have a massive amount of Lumina stored in her body...",
  ui_story_5061_50610202_36_dialog_content = "And when I woke her up with my powers, she started using her Luminatics subconsciously!",
  ui_story_5061_50610202_37_dialog_content = "<color=#e8d9bb>(Cracking sounds)</color>",
  ui_story_5061_50610202_38_dialog_content = "It sounds like the ice is starting to split apart.",
  ui_story_5061_50610202_39_dialog_content = "The Lumina that created this ice is rapidly flowing out. At this rate, she might be able to break herself out. This is great!",
  ui_story_5061_50610202_40_dialog_content = "Great, my foot! What if she sets off an avalanche or something?!",
  ui_story_5061_50610202_41_dialog_content = "We need to retreat to a safe distance before we end up buried with the rest of those Eclipsites!",
  ui_story_5061_50610202_42_dialog_content = "Roaaar—",
  ui_story_5061_50610202_43_dialog_content = "That's all it took to break them out?!",
  ui_story_5061_50610202_44_dialog_content = "Oh no... They're heading right for us!",
  ui_story_5061_50610202_45_dialog_content = "Eclipsites truly are fascinating creatures. If our lives weren't in so much danger, I'd love to study them more closely...",
  ui_story_5061_50610202_46_dialog_content = "<color=#e8d9bb>(Grunts)</color>",
  ui_story_5061_50610202_47_dialog_content = "Thankfully, there aren't too many of them. I should be able to draw their attention while you escape.",
  ui_story_5061_50610202_48_dialog_content = "You're gonna fight them all by yourself?! They're not exactly interested in your research, you know!",
  ui_story_5061_50610202_49_dialog_content = "Don't worry. As a demi-human, I'm more than capable of fending for myself. Besides, I've been in this kind of situation tons of times.",
  ui_story_5061_50610202_50_dialog_content = "At the very least, I should be able to survive their attacks until they wear themselves out.",
  ui_story_5061_50610202_51_dialog_content = "That's a... very unique strategy.",
  ui_story_5061_50610202_52_dialog_content = "But since I'm here, I'll do everything I can to help you win. I'm a Caelestite, I won't let you down.",
  ui_story_5061_50610202_53_dialog_content = "I've got your back! Let's show these monsters what happens when we follow the flow of Lumina!",
  ui_story_5061_50610202_54_dialog_content = "Roaaar—!",
  ui_story_5061_50610202_55_dialog_content = "Urgh! I-I'm not done yet...",
  ui_story_5061_50610202_56_dialog_content = "Focus, Antony! You need to follow the path of Lumina at your feet—Huh?",
  ui_story_5061_50610202_57_dialog_content = "M-My feet... they're frozen?!",
  ui_story_5061_50610202_58_dialog_content = "The temperature is dropping drastically...",
  ui_story_5061_50610202_59_dialog_content = "Who's... there?",
  ui_story_5061_50610202_60_dialog_content = "Graagh!",
  ui_story_5061_50610302_1_dialog_content = "Whoa!",
  ui_story_5061_50610302_2_dialog_content = "The blizzard finally let up... Are you okay?",
  ui_story_5061_50610302_3_dialog_content = "I'm fine, but what about her...?",
  ui_story_5061_50610302_4_dialog_content = "...",
  ui_story_5061_50610302_5_dialog_content = "Careful!",
  ui_story_5061_50610302_6_dialog_content = "Her pulse and breathing are normal, but she's as cold as ice and her face looks a little pale...",
  ui_story_5061_50610302_7_dialog_content = "What should we do now?",
  ui_story_5061_50610302_8_dialog_content = "Wake her up and try to keep her conscious. I'll go scout out a path to the nearest village.",
  ui_story_5061_50610302_9_dialog_content = "No problem.",
  ui_story_5061_50610302_10_dialog_content = "Sorry if this is a little forceful... But the best way to fully awaken you is by entering your mind again!",
  ui_story_5061_50610302_11_dialog_content = "Wake up!!!",
  ui_story_5061_50610302_12_dialog_content = "Ah?!",
  ui_story_5061_50610302_13_option_content = "Er, hi there... Are you alright?",
  ui_story_5061_50610302_14_dialog_content = "Sorry for waking you up like that. Are you hurt at all? Do you remember anything?",
  ui_story_5061_50610302_15_dialog_content = "Who are you? I-I've never seen you before in my life...",
  ui_story_5061_50610302_16_option_content = "Hmm, how strange.",
  ui_story_5061_50610302_17_dialog_content = "Are you some sort of ice pop goddess? That power you unleashed earlier was insane!",
  ui_story_5061_50610302_18_dialog_content = "Wh-What do you mean, ice pop goddess?",
  ui_story_5061_50610302_19_dialog_content = "Who are you, and what are you talking about?!",
  ui_story_5061_50610302_20_dialog_content = "Well, my name is PlayerName, and I'm a Caelestite. My friend and I found you trapped in the ice...",
  ui_story_5061_50610302_21_dialog_content = "... Or at least you were trapped, but then you broke out of it just a few minutes ago.",
  ui_story_5061_50610302_22_dialog_content = "How do you feel? Does anything hurt?",
  ui_story_5061_50610302_23_dialog_content = "A Caelestite...? What would a Caelestite be doing here...",
  ui_story_5061_50610302_24_dialog_content = "The ice... I remember fighting against a horde of Eclipsites, but then...",
  ui_story_5061_50610302_25_dialog_content = "Wait... Am I dead? Could this place be the afterlife...?",
  ui_story_5061_50610302_26_dialog_content = "... Wrong on all accounts. We're on a mountain near the border of Northland, and we're still very much alive.",
  ui_story_5061_50610302_27_dialog_content = "A mountain near the border of Northland... That's right! I came here searching for my sister!",
  ui_story_5061_50610302_28_dialog_content = "<color=#FFB400>Sis</color>... Tell me, did they manage to rescue the other <color=#FFB400>patrollers</color> too?",
  ui_story_5061_50610302_29_dialog_content = "You mean there are other people still trapped in the ice?",
  ui_story_5061_50610302_30_dialog_content = "No, I mean the...",
  ui_story_5061_50610302_31_dialog_content = "Wait, you mean you don't know?! This is where the <color=#FFB400>Aurorastorm</color> happened! The Court dispatched dozens of patrollers to investigate!",
  ui_story_5061_50610302_32_dialog_content = "Except... None of them ever came back. Are you sure you didn't see anyone else?",
  ui_story_5061_50610302_33_dialog_content = "(I didn't know anything about this when I came to Northland... Antony didn't mention anything either.)",
  ui_story_5061_50610302_34_dialog_content = "My name's Zarya. My sister, Alina, she's the captain of the patrollers. Tell me, did you truly not see anyone else out here?",
  ui_story_5061_50610302_35_dialog_content = "I'm really sorry, but I haven't seen... Wait, what's that?!",
  ui_story_5061_50610302_36_dialog_content = "Roaaar—",
  ui_story_5061_50610302_37_dialog_content = "(Crap! I got so caught up talking to her. I completely forgot to watch our surroundings!)",
  ui_story_5061_50610302_38_dialog_content = "... Bloom, Frostlight!",
  ui_story_5061_50610302_39_dialog_content = "Ugh—",
  ui_story_5061_50610302_40_dialog_content = "(So powerful... Even though she's not at her full strength, she took out four Eclipsites with a single attack!)",
  ui_story_5061_50610302_41_dialog_content = "There are Eclipsites here... That means my sister is in even greater danger!",
  ui_story_5061_50610302_42_dialog_content = "I.. I have to find her right away! Alina!",
  ui_story_5061_50610302_43_dialog_content = "Hang on! You just woke up not long ago! It's too dangerous to fight in your current condition!",
  ui_story_5061_50610302_44_dialog_content = "But my sister could be in danger too!",
  ui_story_5061_50610302_45_dialog_content = "I don't understand how or why, but I finally have a way to fight the Eclipsites now!",
  ui_story_5061_50610302_46_dialog_content = "If I can't save my family with the power, then what good am I—",
  ui_story_5061_50610302_47_dialog_content = "<color=#e8d9bb>Plop!</color>",
  ui_story_5061_50610302_48_dialog_content = "Hey! Pull yourself together! There will be no hope for you at all if you pass out in a place like this!",
  ui_story_5061_50610302_49_dialog_content = "I-If something happens to me, then please... Help me find my sister, and tell her, tell her that I don't want to be left again.",
  ui_story_5061_50610302_50_dialog_content = "...",
  ui_story_5061_50610302_51_dialog_content = "Hey—!",
  ui_story_5061_50610302_52_dialog_content = "Breath of Spring—",
  ui_story_5061_50610302_53_dialog_content = "Are these... flower buds? And why do I feel so comfortable all of a sudden...?",
  ui_story_5061_50610302_54_dialog_content = "Pardon me, but are you PlayerName?",
  ui_story_5061_50610302_55_dialog_content = "Yes, that's me.",
  ui_story_5061_50610302_56_dialog_content = "Um, h-hello... My name is Leah, and I'm a Northland patroller... I-I mean, a patroller-in-training.",
  ui_story_5061_50610302_57_dialog_content = "Mr. Antony asked me to lead everyone down to safety.",
  ui_story_5061_50610302_58_dialog_content = "R-Rest assured, I'm very familiar with the mountain paths and hiding spots in this area. I vow to guide everyone back to Queen Bethlehem's protective range safely.",
  ui_story_5061_50610302_59_dialog_content = "Um, that's everything, I think. Did I miss anything?",
  ui_story_5061_50610401_1_dialog_content = "Here, have some freshly-picked fruit...",
  ui_story_5061_50610401_2_dialog_content = "It's excellent for fending off the cold.",
  ui_story_5061_50610401_3_dialog_content = "I meant to bring more medicine and supplies, but our stocks are extremely limited as it is. I'm sorry...",
  ui_story_5061_50610401_4_dialog_content = "Please don't apologize for that, we're already grateful for your help. Don't you want some, Antony?",
  ui_story_5061_50610401_5_dialog_content = "Oh! Sorry, I wasn't paying attention just now.... Thank you.",
  ui_story_5061_50610401_6_dialog_content = "So, how's Zarya doing?",
  ui_story_5061_50610401_7_dialog_content = "Just as you said earlier, her condition is far from normal. I also detect an enormous amount of Lumina residing in her body.",
  ui_story_5061_50610401_8_dialog_content = "To be honest, an ordinary Aurorian wouldn't be able to bear this much Lumina.",
  ui_story_5061_50610401_9_dialog_content = "However, not only was she able to survive being encased in ice, she also managed to break out of it herself. That's nothing ordinary.",
  ui_story_5061_50610401_10_dialog_content = "Indeed. I was just as shocked to find out she was still alive when I probed her mind.",
  ui_story_5061_50610401_11_dialog_content = "Communicating with her hasn't been easy though. She keeps going on about patrollers and her sister, and something about the \"Aurorastorm\"...",
  ui_story_5061_50610401_12_dialog_content = "She wouldn't listen to a word I said.",
  ui_story_5061_50610401_13_dialog_content = "The patrollers have been fine, and no one's missing lately, right, Leah?",
  ui_story_5061_50610401_14_dialog_content = "Oh! W-Were you talking to me...?",
  ui_story_5061_50610401_15_dialog_content = "Yes, you're right. Every patroller has returned from their post, safe and sound.",
  ui_story_5061_50610401_16_dialog_content = "That lines up with my understanding as well. This is Northland, after all; so long as we stay within its borders, we should be perfectly safe.",
  ui_story_5061_50610401_17_dialog_content = "Everyone knows that. In the event of an emergency, we all know to retreat to the Queen's territory for safety.",
  ui_story_5061_50610401_18_dialog_content = "I have a question.",
  ui_story_5061_50610401_19_dialog_content = "The Beacon of Northland... Can it really protect all of Northland with just Queen Bethlehem's power?",
  ui_story_5061_50610401_19X1_dialog_content = "Ever since my very first visit to Northland, I've noticed that everyone keeps talking about protection granted by the Queen and the Beacon.",
  ui_story_5061_50610401_20_dialog_content = "After my last trip to the Winter Palace, I haven't stopped worrying about her well-being.",
  ui_story_5061_50610401_20X1_dialog_content = "I know Queen Bethlehem is one of the most noble and powerful Aurorians in all of Astra.",
  ui_story_5061_50610401_21_dialog_content = "She told me that the worst part was already in the past, and that I shouldn't worry anymore... But is she really fine?",
  ui_story_5061_50610401_21X1_dialog_content = "And what exactly makes the Beacon so special? Is it really able to cover an entire nation in a protective barrier?",
  ui_story_5061_50610401_22_dialog_content = "Her Majesty is... the most trustworthy and reliable person I know! If she says something, then it must be true!",
  ui_story_5061_50610401_22X1_dialog_content = "And yes, it really is that special! So long as the Beacon remains lit, no Eclipsite can cross into Northland.",
  ui_story_5061_50610401_23_dialog_content = "I'm sure there's more to the Beacon than that. After all, as our sole defense against the Eclipsites for over a millennium, it must contain all manner of secrets within its walls.",
  ui_story_5061_50610401_23X1_dialog_content = "Simply put, the Beacon is the unique defense structure of Northland, just like Lumopolis and Illumina have theirs.",
  ui_story_5061_50610401_24_dialog_content = "As residents of Northland, wholeheartedly believing in our queen is the first step to helping her.",
  ui_story_5061_50610401_24X1_dialog_content = "The Beacon is our greatest weapon, as well as our greatest defense.",
  ui_story_5061_50610401_25_dialog_content = "However, I'm far more interested in the Aurorastorm...",
  ui_story_5061_50610401_26_dialog_content = "Are you sure Miss Zarya said it?",
  ui_story_5061_50610401_27_dialog_content = "Yes, and I remember it clearly too. She was determined to find her sister and the other patrollers, which is why she came out here in the first place.",
  ui_story_5061_50610401_28_dialog_content = "But aside from what happened with her, nothing else in this area seems out of the ordinary.",
  ui_story_5061_50610401_29_dialog_content = "I see. It concerns me because I've been searching for clues related to the Aurorastorm recently.",
  ui_story_5061_50610401_30_dialog_content = "In fact, it's the very reason I came to Cedar Peak.",
  ui_story_5061_50610401_31_dialog_content = "I believe my next step is to take a comprehensive survey of the area. Only then will I be able to produce a more specific conclusion.",
  ui_story_5061_50610401_32_dialog_content = "With any luck, I'll be able to ascertain more about Miss Zarya's predicament!",
  ui_story_5061_50610401_33_dialog_content = "We're counting on you, Antony. I'd like to know more about the strange Lumina that I sensed from her earlier too.",
  ui_story_5061_50610401_34_dialog_content = "That energy was purer than anything I've ever experienced...",
  ui_story_5061_50610401_35_dialog_content = "Understood. Please continue taking good care of her while I gather more information.",
  ui_story_5061_50610401_36_dialog_content = "Um, should I try to find a doctor?",
  ui_story_5061_50610401_37_dialog_content = "I don't think that's necessary. She isn't sick or injured, as far as I can tell. My first aid should be enough for now.",
  ui_story_5061_50610401_38_dialog_content = "You really know your stuff, Antony. Not only are you a strong fighter, but you even know how to give medical treatment!",
  ui_story_5061_50610401_39_dialog_content = "I'm curious to know more about your research on the origins of Aurorians too.",
  ui_story_5061_50610401_40_dialog_content = "Did you study in Lumopolis or Illumina, by any chance?",
  ui_story_5061_50610401_41_dialog_content = "Hmm? Not at all, why do you ask?",
  ui_story_5061_50610401_42_dialog_content = "Oh, it's just that a good friend of mine studied abroad in the past, and she really learned a lot in that time. I was just curious to know if you had a similar experience.",
  ui_story_5061_50610401_43_dialog_content = "Oh, I see. No, my only formal education came from literacy classes offered to children in the borderlands.",
  ui_story_5061_50610401_44_dialog_content = "Uh, literacy classes?",
  ui_story_5061_50610401_45_dialog_content = "That's right! Thanks to them, I could read and understand books, and write down my findings.",
  ui_story_5061_50610401_46_dialog_content = "Sorry if I disappointed you somehow, I'm not a renowned scholar from a prestigious academy.",
  ui_story_5061_50610401_47_dialog_content = "Are you kidding me? If anything, that's even more amazing!",
  ui_story_5061_50610401_48_dialog_content = "I've never received a formal education in Astra either. All of my knowledge was passed on to me from my family...",
  ui_story_5061_50610401_49_dialog_content = "But you're a much better student than I'll ever be!",
  ui_story_5061_50610401_50_dialog_content = "There's nothing wrong with that! It doesn't matter how or where you acquire knowledge, as long as your genuine thirst for learning and exploration persists!",
  ui_story_5061_50610401_51_dialog_content = "I'm heading out now!",
  ui_story_5061_50610401_52_dialog_content = "Alright, be careful out there.",
  ui_story_5061_50610401_53_dialog_content = "<color=#e8d9bb>Creak—</color>",
  ui_story_5061_50610401_54_dialog_content = "(Antony closed the door so softly... Probably to avoid waking up Zarya.)",
  ui_story_5061_50610401_55_dialog_content = "(... After struggling and fighting in the snow for so long, the warmth of this room is making me extra sleepy.)",
  ui_story_5061_50610401_56_dialog_content = "(It doesn't look like Zarya's waking up anytime soon. Guess I should try to get some rest too.)",
  ui_story_5061_50610402_1_dialog_content = "(Huh? Where did those Eclipsites go? It's too warm here, and my mouth's so dry...)",
  ui_story_5061_50610402_2_dialog_content = "<color=#e8d9bb>Crackling—</color>",
  ui_story_5061_50610402_3_dialog_content = "(Oh... It was just a dream.)",
  ui_story_5061_50610402_4_dialog_content = "Is everything alright? Miss Zarya?",
  ui_story_5061_50610402_5_dialog_content = "I-It's nothing! I just didn't know how to use this kettle... I didn't realize it was still hot.",
  ui_story_5061_50610402_6_dialog_content = "Um, you're the patient, Miss Zarya. I think you should lay back down again, please...",
  ui_story_5061_50610402_7_dialog_content = "I'm feeling fine now, I promise! Besides, I was just trying to pour this person a cup of water...",
  ui_story_5061_50610402_8_dialog_content = "Emm... Zarya, you're awake? What are you two doing?",
  ui_story_5061_50610402_9_dialog_content = "And who put this coat on me?",
  ui_story_5061_50610402_10_dialog_content = "That was Miss Zarya's doing. When she came to, she found you sleeping at her bedside...",
  ui_story_5061_50610402_11_dialog_content = "She felt so indebted to you because of your kindness that she asked me to bring you this coat!",
  ui_story_5061_50610402_12_dialog_content = "I-I have no idea what you're talking about. I mean yes, he did help assist me greatly on the mountain earlier...",
  ui_story_5061_50610402_13_dialog_content = "But I also rescued him from a pack of bloodthirsty Eclipsites. Surely that makes us equal, right...?",
  ui_story_5061_50610402_14_dialog_content = "B-Besides, as an outsider, he deserves to be shown true Northland hospitality, don't you think?!",
  ui_story_5061_50610402_15_dialog_content = "...",
  ui_story_5061_50610402_16_dialog_content = "M-Maybe it's because I'm still in training, but I didn't really understand anything you said just now, Miss Zarya...",
  ui_story_5061_50610402_17_dialog_content = "Ah! No, that has nothing to do with it! It's just...",
  ui_story_5061_50610402_18_dialog_content = "Thank you.",
  ui_story_5061_50610402_19_dialog_content = "I appreciate it, but you should really try to stay in bed and rest. Do you still remember what happened on the mountain?",
  ui_story_5061_50610402_20_dialog_content = "I do. I was going to search for my sister, but then you stopped me... Why did you do that?!",
  ui_story_5061_50610402_21_dialog_content = "If I didn't, you would've ended up frozen again or in an Eclipsite's stomach. Do either of those sound good to you?",
  ui_story_5061_50610402_22_dialog_content = "You didn't want to listen at all, but I ended up having to carry you all the way back.",
  ui_story_5061_50610402_23_dialog_content = "Y-You what? You carried me down the mountain...?",
  ui_story_5061_50610402_24_dialog_content = "I-I see... But I never asked you to do that, you know! I would have been just fine if you left me out there!",
  ui_story_5061_50610402_25_dialog_content = "Just give it a rest already, would you? You sound like a little kid right now!",
  ui_story_5061_50610402_26_dialog_content = "... But even so, I know I should repay you properly for saving my life. That's not something a child would say, now is it?",
  ui_story_5061_50610402_27_dialog_content = "Fine, fine... But if anyone deserves your thanks, it's Mr. Antony and Leah. They're the ones who found you and brought you medicine.",
  ui_story_5061_50610402_28_dialog_content = "Yes, I know.",
  ui_story_5061_50610402_29_dialog_content = "Are you feeling better now? If you're up to answering some questions, maybe we can figure out a way to find your sister.",
  ui_story_5061_50610402_30_dialog_content = "Sure.",
  ui_story_5061_50610402_31_dialog_content = "First of all, what were you doing trapped in the ice up there?",
  ui_story_5061_50610402_32_dialog_content = "... I'd rather not talk about it.",
  ui_story_5061_50610402_33_dialog_content = "Hey! You just agreed to talk things out, and now you're going back on your word?!",
  ui_story_5061_50610402_34_dialog_content = "Y-You're right, sorry.",
  ui_story_5061_50610402_35_dialog_content = "As I mentioned before, all the team sent by the Court to investigate the Aurorastorm was never seen or heard from again.",
  ui_story_5061_50610402_36_dialog_content = "My sister was among them as well.",
  ui_story_5061_50610402_37_dialog_content = "I went to their last known location and searched for hours. Eventually, I managed to hear my sister's voice nearby, only to find them under attack by a horde of Eclipsites.",
  ui_story_5061_50610402_38_dialog_content = "There were so many of them, and I was worried that I wouldn't reach my sister in time.",
  ui_story_5061_50610402_39_dialog_content = "So while the battle raged on, I hid under a pile of Eclipsite carcasses and prayed with all my heart...",
  ui_story_5061_50610402_40_dialog_content = "I prayed that I could find the strength I needed to rescue my sister...",
  ui_story_5061_50610402_41_dialog_content = "Suddenly, as if my prayers had been answered, an enormous power welled up inside of me. Unfortunately, I completely lost control of it, and my Lumina ran wild across the battlefield.",
  ui_story_5061_50610402_42_dialog_content = "The Eclipsites were all but wiped out, but at the same time, I ended up trapped in a frozen tomb made by my own Luminatics.",
  ui_story_5061_50610402_43_dialog_content = "There I laid dormant... Until you woke me up today.",
  ui_story_5061_50610402_44_dialog_content = "So you trapped yourself in the ice, huh? Your story just keeps getting crazier, you know.",
  ui_story_5061_50610402_45_dialog_content = "I-It's not like I wanted this to happen... I've never been particularly good at controlling my power.",
  ui_story_5061_50610402_46_dialog_content = "So go ahead and laugh! As long as you help me find my sister afterward, you can laugh all you want...",
  ui_story_5061_50610402_47_dialog_content = "I'm still having some difficulty telling my memories and reality apart...",
  ui_story_5061_50610402_48_dialog_content = "I see.",
  ui_story_5061_50610402_49_dialog_content = "Leah, would you mind telling Zarya about what you told me earlier?",
  ui_story_5061_50610402_50_dialog_content = "S-Sure thing!",
  ui_story_5061_50610402_51_dialog_content = "When we arrived here, PlayerName asked me... If there were any emergencies reported in this area.",
  ui_story_5061_50610402_52_dialog_content = "I told him that this area has been peaceful for quite some time now, since Eclipsites only exist outside of Northland's borders. In addition, every single patrol team has reported back to the palace without incident.",
  ui_story_5061_50610402_53_dialog_content = "The closest thing I've heard regarding missing patrollers is when one of us travels a bit further than usual. When that happens, we simply lose contact for some time. Battles almost never happen, and deaths are even less common...",
  ui_story_5061_50610402_54_dialog_content = "And aside from rumors of people hearing the \"Spirit of the Aurora\" deep within the mountains, there hasn't been any unusual activity reported in this area.",
  ui_story_5061_50610402_55_dialog_content = "In other words, despite our best efforts gathering information, we haven't learned anything related to your sister or the missing patrollers.",
  ui_story_5061_50610402_56_dialog_content = "This means if what you're telling us is true, your sister should be home safe and sound.",
  ui_story_5061_50610402_57_dialog_content = "Really? I would be so relieved if that were true...",
  ui_story_5061_50610402_58_dialog_content = "It's possible that the answer lies somewhere in your mind, Zarya.",
  ui_story_5061_50610402_59_dialog_content = "Huh? Wh-What do you mean?",
  ui_story_5061_50610402_60_dialog_content = "After combining Antony's observations and my own findings...",
  ui_story_5061_50610402_61_dialog_content = "My guess is that you spent too much time trapped in an environment full of a strange type of Lumina. As a result, your memories got a little scrambled.",
  ui_story_5061_50610402_62_dialog_content = "That's why you keep confusing past events with our present reality.",
  ui_story_5061_50610402_63_dialog_content = "M-My memories are \"scrambled\"?",
  ui_story_5061_50610402_64_dialog_content = "In a way, yes. I guess a better way to put it is that some sort of energy has impacted your brain, making it difficult to understand what's going on around you.",
  ui_story_5061_50610402_65_dialog_content = "So, in other words, I've gotten more stupid?!",
  ui_story_5061_50610402_66_dialog_content = "I suppose you're right... After all, instead of rescuing my sister, I ended up trapping myself in the ice...",
  ui_story_5061_50610402_67_dialog_content = "I'm totally useless... I don't think there's a bigger fool in the world than myself.",
  ui_story_5061_50610402_68_dialog_content = "C'mon Zarya, don't say that! Just look at your Luminatics from earlier! I don't think someone useless could do something like that!",
  ui_story_5061_50610402_69_dialog_content = "In the blink of an eye, you saved me from certain doom AND wiped out every single Eclipsite around us!",
  ui_story_5061_50610402_70_dialog_content = "The Lumina from your attack was pretty. It looked just like your hair...",
  ui_story_5061_50610402_71_dialog_content = "When Leah first saw you, she honestly thought you were the Spirit of the Aurora!",
  ui_story_5061_50610402_72_dialog_content = "It's true! The way your hair sparkles and glows... It's as if the Aurora blessed it!",
  ui_story_5061_50610402_73_dialog_content = "... Sparkles? What sparkles?",
  ui_story_5061_50610402_74_dialog_content = "Oh, uh... It's a little awkward to admit, but I was just so fascinated by Miss Zarya's hair, since mine is so short...",
  ui_story_5061_50610402_75_dialog_content = "So I helped her brush it while she was asleep. That's when I discovered...",
  ui_story_5061_50610402_76_dialog_content = "Her hair gives off a faint glow, just like a magical relic from the ancient past! You know, like in the stories!",
  ui_story_5061_50610402_77_dialog_content = "M-My hair?! But... But this isn't... My hair wasn't always this color!",
  ui_story_5061_50610402_78_dialog_content = "She's right, your hair is emitting Lumina. This must be a side-effect of being trapped inside your Luminatics for so long!",
  ui_story_5061_50610402_79_dialog_content = "You're like a walking fountain of Lumina, constantly releasing it into the space around you!",
  ui_story_5061_50610402_80_dialog_content = "This must be what Antony was talking about earlier... Maybe we should go ask him more about it?",
  ui_story_5061_50610402_81_dialog_content = "Do you have any way of reaching him, Leah?",
  ui_story_5061_50610402_82_dialog_content = "I do, actually! Come with me, and I'll take you to the village where he usually conducts his research.",
  ui_story_5061_50610402_83_dialog_content = "If I had to guess, he's probably there right now.",
  ui_story_5061_50610501_1_dialog_content = "Look who's here! Leah, our Spring Elf!",
  ui_story_5061_50610501_2_dialog_content = "Patrolling on the mountain road again today?",
  ui_story_5061_50610501_3_dialog_content = "Th-That's right... But I'm not on my usual patrol route today.",
  ui_story_5061_50610501_4_dialog_content = "I have... some personal matters to attend to.",
  ui_story_5061_50610501_5_dialog_content = "Are these two your friends, Leah?",
  ui_story_5061_50610501_6_dialog_content = "Well, this is unexpected. Outsiders are showing up in this remote area. And you, young fella, don't really seem like you're from Northland.",
  ui_story_5061_50610501_7_dialog_content = "Huh? You mean me?",
  ui_story_5061_50610501_8_dialog_content = "Absolutely. Time's really flown by, and now we've got tourists coming around here. Back in the day, this was actually the frontline against the Eclipsites invasion...",
  ui_story_5061_50610501_9_dialog_content = "The mountain road was all snowed in and blocked off. We locals, could only stick close behind the patrols...",
  ui_story_5061_50610501_10_dialog_content = "Pardon me, but which patrol team are you referring to?",
  ui_story_5061_50610501_11_dialog_content = "I don't think he's talking about your sister, Miss Zarya. If anything... He's referring to my parents.",
  ui_story_5061_50610501_12_dialog_content = "Huh? Your parents were also Northland patrollers, Leah?",
  ui_story_5061_50610501_13_dialog_content = "Yes, but... They passed away a long time ago.",
  ui_story_5061_50610501_14_dialog_content = "Oh, I'm sorry. I didn't mean to bring up such a sensitive subject.",
  ui_story_5061_50610501_15_dialog_content = "Don't you guys know that Leah's an orphan from the patrols?",
  ui_story_5061_50610501_16_dialog_content = "The truth is, even though the Eclipsites aren't swarming here like they were years back, this job's still pretty risky.",
  ui_story_5061_50610501_17_dialog_content = "This isn't a place like the Winter Palace or Lake Mirror, watched over by Her Majesty the Queen and Lady Nikinis...",
  ui_story_5061_50610501_18_dialog_content = "We've only got the members of patrols to rely on. But the thought that kids like Leah gotta handle all this is kinda hard to watch.",
  ui_story_5061_50610501_19_dialog_content = "It's... It's no trouble at all, really! Her Majesty entrusted me with the Staff of Spring, and I have so many friends helping me...",
  ui_story_5061_50610501_20_dialog_content = "Handling a few Eclipsites isn't a problem at all... I also get paid vacation time, which is even nicer...",
  ui_story_5061_50610501_21_dialog_content = "Sigh. No matter what, these things still need someone to deal with. And I'm not exactly in a position to give you more comfort.",
  ui_story_5061_50610501_22_dialog_content = "All we can do is to thank you for your dedication.",
  ui_story_5061_50610501_23_dialog_content = "A job that needs to be done...",
  ui_story_5061_50610501_24_dialog_content = "You know, I've noticed that you look a little lonely sometimes.",
  ui_story_5061_50610501_25_dialog_content = "You didn't choose this job just to be a patroller, did you? If anything, you probably wanted to feel closer to your parents by following in their footsteps...",
  ui_story_5061_50610501_26_dialog_content = "Am I right?",
  ui_story_5061_50610501_27_dialog_content = "Ah... You saw right through me...",
  ui_story_5061_50610501_28_dialog_content = "That's because I feel exactly the same way sometimes.",
  ui_story_5061_50610501_29_dialog_content = "Really? You feel the same too?",
  ui_story_5061_50610501_30_dialog_content = "To be honest, I didn't really know what I was thinking when I accepted the Staff of Spring and became a patroller...",
  ui_story_5061_50610501_31_dialog_content = "Maybe it was to get closer to my parents... Or maybe I was so impressed by Her Majesty that I wanted to fight at her side...",
  ui_story_5061_50610501_32_dialog_content = "But taking up the Staff of Spring... I made that choice all on my own!",
  ui_story_5061_50610501_33_dialog_content = "And I wanted to give meaning to that choice! That's why... That's why I decided to keep being a patroller!",
  ui_story_5061_50610501_34_dialog_content = "That's an incredible realization, Leah.",
  ui_story_5061_50610501_35_dialog_content = "The decision to persevere in your chosen path...",
  ui_story_5061_50610501_36_dialog_content = "Hey, little Leah! Can you help me find out where those two kids from next door ran off?",
  ui_story_5061_50610501_37_dialog_content = "Just promised their folks I'd keep an eye on 'em for a bit, but poof, they're gone in the blink of an eye!",
  ui_story_5061_50610501_38_dialog_content = "Oh, sure! In fact... I think I know just where to look for them!",
  ui_story_5061_50610501_39_dialog_content = "But before that, may I ask... Have you seen Mr. Antony?",
  ui_story_5061_50610501_40_dialog_content = "Who're you talkin' about? Is he from our village?",
  ui_story_5061_50610501_41_dialog_content = "Er, not really. Mr. Antony is a very kind-hearted scholar who moved here recently. He often reads to the children and teaches them about stars and how to use them to navigate.",
  ui_story_5061_50610501_42_dialog_content = "Oh, yes. You jogged my memory—someone like that livin' close by the village.",
  ui_story_5061_50610501_43_dialog_content = "The kids say he's always tinkering with some strange device, but he's friendly enough.",
  ui_story_5061_50610501_44_dialog_content = "So, he's a scholar, you say? I can't quite picture it. Shouldn't scholars be cooped up indoors reading books all day?",
  ui_story_5061_50610501_45_dialog_content = "But this fella, he's always putting that brawny body of his to use, running around in the mountains and returning all battered and bruised.",
  ui_story_5061_50610501_46_dialog_content = "So, what exactly does he study?",
  ui_story_5061_50610501_47_dialog_content = "He's, uh, researching the origins of Aurorians, like where we came from and where we're going. You know, that kind of stuff.",
  ui_story_5061_50610501_48_dialog_content = "Well, that's pretty odd. Running wild in the mountains every single day, does that really help him figure out all this stuff?",
  ui_story_5061_50610501_49_dialog_content = "Why doesn't he study what's causing the crops here to wither away? There weren't many alternatives that could grow in this cold place to begin with.",
  ui_story_5061_50610501_50_dialog_content = "I can't really tell him what to do, sorry. Besides, not everything has its answer.",
  ui_story_5061_50610501_51_dialog_content = "But still, Mr. Antony may have researched something related to it...",
  ui_story_5061_50610501_52_dialog_content = "He once told me... That \"spring\" means two different things for crops and Aurorians.",
  ui_story_5061_50610501_53_dialog_content = "Two different springs? What could that possibly mean?",
  ui_story_5061_50610501_54_dialog_content = "Guess we'll just have to ask him about it when we find him.",
  ui_story_5061_50610501_55_dialog_content = "Either way, I have to go see him.",
  ui_story_5061_50610501_56_dialog_content = "Same here. Those two kids enjoy asking Mr. Antony lots of questions, just like me...",
  ui_story_5061_50610501_57_dialog_content = "They're probably learning something new at his house if they're not in the village right now.",
  ui_story_5061_50610502_1_dialog_content = "Phew... We're finally here.",
  ui_story_5061_50610502_2_dialog_content = "You said his house is on the way to Cedar Peak, but he practically lives at the foot of the mountain.",
  ui_story_5061_50610502_3_dialog_content = "Well, he did come here to investigate the mountain...",
  ui_story_5061_50610502_4_dialog_content = "There are so many books in here... And look, a radio.",
  ui_story_5061_50610502_5_dialog_content = "He owns more books than a library... Wait, what's a \"ready-o\"?",
  ui_story_5061_50610502_6_dialog_content = "It's pronounced \"radio,\" Miss Zarya. From what I understand, most outsiders buy them in Umbraton...",
  ui_story_5061_50610502_7_dialog_content = "Are these... Mr. Antony's notes?",
  ui_story_5061_50610502_8_dialog_content = "Let me see if there's any clue in it...",
  ui_story_5061_50610502_9_dialog_content = "I'll look around too... Oh my, he really has investigated the issue of the local crops growing poorly!",
  ui_story_5061_50610502_10_dialog_content = "\"Year after year, the fields around Cedar Village fail to produce healthy crops, and the situation only seems to be growing worse with each passing year. I suspect that the abnormal Lumina in the area is responsible.\"",
  ui_story_5061_50610502_11_dialog_content = "... Mr. Antony's handwriting is cute, don't you think? It looks just like a child's handwriting!",
  ui_story_5061_50610502_12_dialog_content = "(Well that makes sense, considering his only formal education was from when he was a kid...)",
  ui_story_5061_50610502_13_dialog_content = "He also has a few hand-drawn schematics in here. A \"multi-functional trekking pole\"? Wow, I had no idea Mr. Antony designed and built that walking pole he always carries around!",
  ui_story_5061_50610502_14_dialog_content = "It looks like he's gone through a couple of versions too. According to his notes, it kept breaking during fights with Eclipsites...",
  ui_story_5061_50610502_15_dialog_content = "So, he focused on strengthening its design over the next few versions... That hardly sounds \"multi-functional\" to me!",
  ui_story_5061_50610502_16_dialog_content = "I'm well aware of that. As a demi-human, I'm more than capable of fending for myself. Besides, I've been in this kind of situation countless times before!",
  ui_story_5061_50610502_17_dialog_content = "At the very least, I should be able to survive their attacks until they wear themselves out.",
  ui_story_5061_50610502_18_dialog_content = "Though when it comes to him... Endurance is probably the most useful function anything could have.",
  ui_story_5061_50610502_19_dialog_content = "PlayerName? It also mentions something called a \"transmitter function.\" What does that mean?",
  ui_story_5061_50610502_20_dialog_content = "<size=45>Look out! Eclipsites!</size>",
  ui_story_5061_50610502_21_dialog_content = "Eclipsites?! Where?!?",
  ui_story_5061_50610502_22_dialog_content = "Hahaha, gotcha! You're such a wuss!",
  ui_story_5061_50610502_23_dialog_content = "There you are, you two! Your family's been worried sick! Can't you at least tell them where you're going before disappearing from the village?",
  ui_story_5061_50610502_24_dialog_content = "She's right, you know! It's not nice to play pranks like this either!",
  ui_story_5061_50610502_25_dialog_content = "Children who cry Eclipsites for attention are usually the first to get eaten!",
  ui_story_5061_50610502_26_dialog_content = "Geez, why you talkin' like my grandma? Nobody scares kids like that these days!",
  ui_story_5061_50610502_27_dialog_content = "Besides, we know this area like the back of our hands. We're perfectly aware of where it's risky and where it's safe.",
  ui_story_5061_50610502_28_dialog_content = "If you don't believe us, we can show you our special move—<color=#FFB400>Eclipsite Fishing</color>!",
  ui_story_5061_50610502_29_dialog_content = "Wanna see it? We lure the Eclipsites to chase us, then bring them into the lighthouse's glow. And bam! The Eclipsites are toast!",
  ui_story_5061_50610502_30_dialog_content = "And some Eclipsites finally realize what's going on and skedaddle like chickens—can't even describe how funny it is, hahaha!",
  ui_story_5061_50610502_31_dialog_content = "Are you kids out of your minds?! That's way too dangerous!",
  ui_story_5061_50610502_32_dialog_content = "These children truly don't understand how blessed they are to live in peace...",
  ui_story_5061_50610502_33_dialog_content = "Cause it's so boring here, you know. There's not much exciting stuff on the border.",
  ui_story_5061_50610502_34_dialog_content = "Except for what Mr. Antony said. That's pretty fascinating.",
  ui_story_5061_50610502_35_dialog_content = "What did he say?",
  ui_story_5061_50610502_36_dialog_content = "Mr. Antony said that the things in fairy tales were real!",
  ui_story_5061_50610502_37_dialog_content = "Do you remember that old fairy tale? The one that talks about Northland once being a lush, green place full of life?",
  ui_story_5061_50610502_38_dialog_content = "I have a feeling this isn't just a fairy tale, but a true story from the past!",
  ui_story_5061_50610502_39_dialog_content = "For real?",
  ui_story_5061_50610502_40_dialog_content = "I found something that might prove it too! The rings of an ancient tree found frozen in ice for countless centuries...",
  ui_story_5061_50610502_41_dialog_content = "Changes in an area's climate can be seen in the rings of trees, you know!",
  ui_story_5061_50610502_42_dialog_content = "The sparser sections of tree rings indicate a relatively warmer growth environment at that time, while the denser parts indicate the exact opposite. As for the tree I found, the innermost rings are exceptionally sparse.",
  ui_story_5061_50610502_43_dialog_content = "Which means that at some point, Northland was a warm place! It might have even experienced an honest-to-goodness spring season!",
  ui_story_5061_50610502_44_dialog_content = "That means the fairy tales are real, not just something made up to fool kids! I'm gonna go tell Grandma about this!",
  ui_story_5061_50610502_45_dialog_content = "But again, why is it so cold in Northland now?",
  ui_story_5061_50610502_46_dialog_content = "Well, Northland still sits at a very high altitude. It's also very close to the land of Eternal Night, which I'm sure is also an extremely cold place.",
  ui_story_5061_50610502_47_dialog_content = "Indeed, if Northland truly used to be a warm place... Then that means the Twilight Circle we're all familiar with wasn't here...",
  ui_story_5061_50610502_48_dialog_content = "What exactly did the world look like all those years ago...?",
  ui_story_5061_50610502_49_dialog_content = "Mr. Antony, Mr. Antony?",
  ui_story_5061_50610502_50_dialog_content = "Your voice went low, and what you were saying was too obscure. We can't make it out.",
  ui_story_5061_50610502_51_dialog_content = "Sorry about that, kids. The world is so full of unsolved mysteries that even I have difficulty understanding things.",
  ui_story_5061_50610502_52_dialog_content = "That's why it's best not to trouble other people with this kind of stuff, okay?",
  ui_story_5061_50610502_53_dialog_content = "I'm all about unsolved mysteries! Do you know the deal with Lake Mirror's surface, the Beacon's glow, and the Queen's everlasting ice?",
  ui_story_5061_50610502_54_dialog_content = "Hahaha! While it would be rather impolite to inquire about Her Majesty's secrets, with enough studying and communication...",
  ui_story_5061_50610502_55_dialog_content = "It's possible that we'll know someday.",
  ui_story_5061_50610502_56_dialog_content = "I wanna study with you! I'm curious about whether the Spirit of Aurora is real too!",
  ui_story_5061_50610502_57_dialog_content = "You're more than welcome to join me someday, but be warned: this line of work is full of danger and difficulty. You'll need to train both your minds and your bodies if you want to keep up.",
  ui_story_5061_50610502_58_dialog_content = "Well, little ones? Do you think these pranks of yours count as training?",
  ui_story_5061_50610502_59_dialog_content = "I'm certain Mr. Antony taught you better, yes?",
  ui_story_5061_50610502_60_dialog_content = "I'm sorry...",
  ui_story_5061_50610502_61_dialog_content = "... Mr. Antony said we shouldn't mess with Eclipsites, and we should value the Beacon's power 'cause Queen's been putting in a lot of effort to maintain it.",
  ui_story_5061_50610502_62_dialog_content = "... So, we haven't played the Eclipsite-fishing game since then. We were just showing off to you just now...",
  ui_story_5061_50610502_63_dialog_content = "I'm glad you understand. You make everyone worry about you even when you were just showing off, you know?",
  ui_story_5061_50610502_64_dialog_content = "Hmm... I'm sorry.",
  ui_story_5061_50610502_65_dialog_content = "Miss Zarya... That was amazing! I-I guess I'm not very good at having hard conversations with others...",
  ui_story_5061_50610502_66_dialog_content = "Honestly, I was pretending to be someone else just now. I'm just as surprised that it worked out so well...",
  ui_story_5061_50610502_67_dialog_content = "T-To tell the truth, I'd like to learn how to be more compassionate like Leah...",
  ui_story_5061_50610502_68_dialog_content = "You know, you were pretty compassionate when you were asleep.",
  ui_story_5061_50610502_69_dialog_content = "I don't remember asking you—",
  ui_story_5061_50610502_70_dialog_content = "What's Mr. Antony been up to lately? It's been a while since he told us stories the last time...",
  ui_story_5061_50610502_71_dialog_content = "It kinda makes me worry...",
  ui_story_5061_50610502_72_dialog_content = "He must be investigating what's written here in these notes: the Aurorastorm, the strange Lumina, and the frozen cave on Cedar Peak!",
  ui_story_5061_50610502_73_dialog_content = "It says here that a large set of unidentified ruins might exist somewhere inside Cedar Peak...",
  ui_story_5061_50610502_74_dialog_content = "... Could that be the source of the strange Lumina I sensed earlier?",
  ui_story_5061_50610502_75_dialog_content = "(So how is Zarya connected to all of this?)",
  ui_story_5061_50610502_76_dialog_content = "The Aurorastorm... and Cedar Peak...",
  ui_story_5061_50610502_77_dialog_content = "What was I doing before I was frozen? Urgh—",
  ui_story_5061_50610502_78_dialog_content = "(I don't want to stay in the dark forever! I want to know... I want to remember what happened to me!)",
  ui_story_5061_50610601_1_dialog_content = "I didn't think our search would lead us right back to where we found you, Zarya.",
  ui_story_5061_50610601_2_dialog_content = "Are you feeling alright?",
  ui_story_5061_50610601_3_dialog_content = "I'm fine! Besides, I wasn't going to let you return to the mountain on your own!",
  ui_story_5061_50610601_4_dialog_content = "You really shouldn't push yourself. I could've just waited for Leah to come back and escort me here.",
  ui_story_5061_50610601_5_dialog_content = "Like I said! I'm fine, so don't worry about it!",
  ui_story_5061_50610601_6_dialog_content = "Everyone's working so hard to help me right now... What kind of person would I be if I left you to face the cold and the Eclipsites all by yourself...",
  ui_story_5061_50610601_7_dialog_content = "I'm simply looking for answers. In that respect, I'm no different than Leah or Antony...",
  ui_story_5061_50610601_8_dialog_content = "I want to face my past and take responsibility for what I've done, no matter how foolish I may have been. I refuse to pretend that nothing ever happened.",
  ui_story_5061_50610601_9_dialog_content = "Well, it's always good to have a goal in mind.",
  ui_story_5061_50610601_10_dialog_content = "But... Don't you think you should be preparing to go home right now, instead? Or maybe looking for something to change your hair color?",
  ui_story_5061_50610601_11_dialog_content = "... I've already written a letter home telling everyone I'm safe. However, the Courier needs a bit more time to get here.",
  ui_story_5061_50610601_12_dialog_content = "(I just hope the address I remember is still right...)",
  ui_story_5061_50610601_13_dialog_content = "That's why... I need something to do in the meantime.",
  ui_story_5061_50610601_14_dialog_content = "Even if my sister is safe, I can't go home until I understand why I lost control of my powers like that.",
  ui_story_5061_50610601_15_dialog_content = "I just... I really need to go back and find out what on earth happened to me!",
  ui_story_5061_50610601_16_dialog_content = "How beautiful...",
  ui_story_5061_50610601_17_dialog_content = "Huh...? Wh-What are you talking about?!",
  ui_story_5061_50610601_18_dialog_content = "I'm talking about the sky! I guess I didn't really notice it when we were rescuing you earlier.",
  ui_story_5061_50610601_19_dialog_content = "I heard someone say that the edge of the Twilight Circle wasn't too far from here on our way back down the mountain.",
  ui_story_5061_50610601_20_dialog_content = "O-Oh, so that's what you meant... This is pretty common for those of us who grew up in the borderlands.",
  ui_story_5061_50610601_21_dialog_content = "Before today, I had only ever read about it in Soroz's databases. No wonder Antony was so keen on teaching those kids about it.",
  ui_story_5061_50610601_22_dialog_content = "Not many people dedicate as much time or effort to understanding it. I do believe Mr. Antony is the most passionate person I've ever met in this respect.",
  ui_story_5061_50610601_23_dialog_content = "In much the same way, few people seek to understand the source of the Beacon's power, or the Queen's reasons for protecting Northland.",
  ui_story_5061_50610601_24_dialog_content = "Living a simple life must be pretty nice. Everyone's views are so pure and uncomplicated here.",
  ui_story_5061_50610601_25_dialog_content = "Maybe it has to do with how detached Northland is from the struggles of the rest of the world. It's been exactly the same for countless years.",
  ui_story_5061_50610601_26_dialog_content = "Actually, Northland is fairly different from what I can still remember. The most obvious difference is how easily an outsider like you could appear in this place.",
  ui_story_5061_50610601_27_dialog_content = "I suppose Northland and the Caelestites have something in common, huh? We both isolated ourselves from the world to maintain our neutrality.",
  ui_story_5061_50610601_28_dialog_content = "Do Caelestites have very little contact with the outside world?",
  ui_story_5061_50610601_29_dialog_content = "Yep. To avoid conflict with the rest of the world and live in peace, my people chose to seclude themselves in Eraveil, a place where outsiders hardly ever set foot.",
  ui_story_5061_50610601_30_dialog_content = "Even from a young age, we're taught never to leave or engage with the outside world without permission from our elders.",
  ui_story_5061_50610601_31_dialog_content = "So what made you leave Eraveil?",
  ui_story_5061_50610601_32_dialog_content = "Unfortunately, all of our efforts to stay away from the rest of the world didn't keep us safe from the Eclipsites.",
  ui_story_5061_50610601_33_dialog_content = "Many years ago, a legion of Eclipsites descended on Eraveil, wiping out every one of my people. I was the only survivor.",
  ui_story_5061_50610601_34_dialog_content = "What?! So just like that, the legendary Caelestites... They're all gone now?",
  ui_story_5061_50610601_35_dialog_content = "... I'm so sorry. I didn't mean to bring up such painful memories. You must be feeling lonely.",
  ui_story_5061_50610601_36_dialog_content = "Haha, there's nothing to apologize for! As terrible as it is, I've already come to accept the past.",
  ui_story_5061_50610601_37_dialog_content = "I feel as though I can understand how you feel. Though my life experiences are nothing compared to yours.",
  ui_story_5061_50610601_38_dialog_content = "When I was little, I caused my family so many problems because I couldn't control my Luminatics.",
  ui_story_5061_50610601_39_dialog_content = "My father was especially ashamed of me. He was always so distant, and he kept me locked away at home for fear that I would hurt his business.",
  ui_story_5061_50610601_40_dialog_content = "Eventually, I lost nearly all of my social skills. I had no friends or even the courage to make friends.",
  ui_story_5061_50610601_41_dialog_content = "When I think back on it, my life was really no different than when I was trapped in the ice.",
  ui_story_5061_50610601_42_dialog_content = "You must've suffered the same loneliness... Trapped all alone, with no one for company.",
  ui_story_5061_50610601_43_dialog_content = "In the beginning, yes. I spent nearly all of my childhood trapped in a small space. If I wanted to learn anything about the outside world, I had to rely on Soroz's databases.",
  ui_story_5061_50610601_44_dialog_content = "Over time, I started wondering if I truly existed in the world.",
  ui_story_5061_50610601_45_dialog_content = "And now, even though I can see the world with my own two eyes... That same feeling still finds me every now and then.",
  ui_story_5061_50610601_46_dialog_content = "That's why I choose to keep moving, no matter what. If I don't keep moving, nothing will ever change.",
  ui_story_5061_50610601_47_dialog_content = "My people once lived in this world and even fought to protect it. I'm going to do the same.",
  ui_story_5061_50610601_48_dialog_content = "... You know, talking to you feels like talking to my sister. You're both so strong yet so kind-hearted.",
  ui_story_5061_50610601_49_dialog_content = "Unlike myself, who always makes others upset with my terrible decision-making...",
  ui_story_5061_50610601_50_dialog_content = "If I were more like you, maybe Father wouldn't have turned his back on me. Maybe I would have rescued my sister...",
  ui_story_5061_50610601_51_dialog_content = "Instead of ending up trapped in ice.",
  ui_story_5061_50610601_52_dialog_content = "I just remembered, the Caelestites were supposed to have legendary psychic powers, right? Did you use those powers to awaken me too?",
  ui_story_5061_50610601_53_dialog_content = "That's right. In fact, I'm thinking of using them again right now.",
  ui_story_5061_50610601_54_dialog_content = "You know, you seem pretty out of the loop when it comes to Astra's recent history.",
  ui_story_5061_50610601_55_dialog_content = "In fact, it feels like you were stuck in the ice for a really long time.",
  ui_story_5061_50610601_56_dialog_content = "H-Hey! You're the one introducing me to all kinds of new information! Of course you're going to feel that way!",
  ui_story_5061_50610601_57_dialog_content = "Shhh! I sense Eclipsites!",
  ui_story_5061_50610601_58_dialog_content = "It looks like we're well outside of Queen Bethlehem's invisible barrier.",
  ui_story_5061_50610602_1_dialog_content = "I'll stain the snow with your blood, you monsters!",
  ui_story_5061_50610602_2_dialog_content = "Growl...",
  ui_story_5061_50610602_3_dialog_content = "That was hardly a challenge!",
  ui_story_5061_50610602_4_dialog_content = "That's strange... Something's not right about these Eclipsites.",
  ui_story_5061_50610602_5_dialog_content = "What do you mean?",
  ui_story_5061_50610602_6_dialog_content = "They're trying to retreat from you. Could it be that they can sense your abnormally high levels of Lumina?",
  ui_story_5061_50610602_7_dialog_content = "Hmph, that works just fine for me. If this strange Lumina is that frightening, I might as well just keep it within me.",
  ui_story_5061_50610602_8_dialog_content = "Aside from turning my hair the same color as the Aurora, it doesn't seem to be affecting me in any other way...",
  ui_story_5061_50610602_9_dialog_content = "I'll do my best to control it so I don't freeze your legs again!",
  ui_story_5061_50610602_10_dialog_content = "So you still remember me complaining about that, huh?",
  ui_story_5061_50610602_11_dialog_content = "As long as you avoid my head, we should be good. I don't want to end up frozen AND with different-colored hair.",
  ui_story_5061_50610602_12_dialog_content = "You don't have to sound so scared, you know!",
  ui_story_5061_50610602_13_dialog_content = "I'm just a little nervous from seeing you get so familiar with your attacks. They're only gonna get stronger from here on out...",
  ui_story_5061_50610602_14_dialog_content = "Do you honestly think I could lose control that badly?!",
  ui_story_5061_50610602_15_dialog_content = "It's not completely out of the question, is it? After all, you ended up freezing yourself along with half of Cedar Peak!",
  ui_story_5061_50610602_16_dialog_content = "You said you wanted to face your past no matter how bad it is, right? Or are you trying to shift the blame back on the Spirit of the Aurora?",
  ui_story_5061_50610602_17_dialog_content = "I...",
  ui_story_5061_50610602_18_dialog_content = "Gaah—Graaah...",
  ui_story_5061_50610602_19_dialog_content = "Alright, I admit I may have gotten a little too excited when I felt that power inside me...",
  ui_story_5061_50610602_20_dialog_content = "Good. I'm glad we feel the same way.",
  ui_story_5061_50610602_21_dialog_content = "Speaking of excitement, Mr. Antony is really devoted to his research, isn't he? Do you really think the Aurora is connected to an ancient power source as well?",
  ui_story_5061_50610602_22_dialog_content = "My sister and I witnessed the Aurorastorm for ourselves... Could it have originated in the nearby ruins as well?",
  ui_story_5061_50610602_23_dialog_content = "We probably won't know until we ask Antony himself...",
  ui_story_5061_50610602_24_dialog_content = "But if I had to guess, this strange Lumina is probably the reason you have the power to freeze entire mountains.",
  ui_story_5061_50610602_25_dialog_content = "And from what I can sense, this strange Lumina came from somewhere underground. It may connect to the same source of Lumina that produced the Aurorastorm.",
  ui_story_5061_50610602_26_dialog_content = "Antony says that part of the problem is the lack of recent records on the Aurorastorm... Which means we don't know how long ago it happened.",
  ui_story_5061_50610602_27_dialog_content = "But regardless of when it happened, there aren't any traces of it left...",
  ui_story_5061_50610602_28_dialog_content = "There aren't any traces of the patrollers or the battle they fought back then either...",
  ui_story_5061_50610602_29_dialog_content = "I can't believe my memory has gotten so unreliable...",
  ui_story_5061_50610602_30_dialog_content = "(Huh? It looks like the snow beneath our feet is glowing...)",
  ui_story_5061_50610602_31_dialog_content = "Hmm? Is that a rabbit next to that tree over there?",
  ui_story_5061_50610602_32_dialog_content = "Rabbits are extremely cautious animals. If it's out, this area should be free of any unseen danger...",
  ui_story_5061_50610602_33_dialog_content = "Wait, Zarya! Something doesn't feel right about this place. Let me try using my powers first.",
  ui_story_5061_50610602_34_dialog_content = "Again? Fine... If worst comes to worst, I'll fight off whatever you manage to find.",
  ui_story_5061_50610602_35_option_content = "Force Boost",
  ui_story_5061_50610602_36_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610602_37_dialog_content = "Argh!",
  ui_story_5061_50610602_38_dialog_content = "What was that?! It feels like something just stabbed my head...",
  ui_story_5061_50610602_39_dialog_content = "D-Don't scare me like that! Are you okay...?",
  ui_story_5061_50610602_40_dialog_content = "I... I think I may have awakened something...",
  ui_story_5061_50610602_41_dialog_content = "<color=#e8d9bb>Rumble—!</color>",
  ui_story_5061_50610602_42_dialog_content = "What's going on? What was that noise?!",
  ui_story_5061_50610602_43_dialog_content = "The ground is collapsing!",
  ui_story_5061_50610602_44_dialog_content = "Look out, Zarya!",
  ui_story_5061_50610602_45_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5061_50610602_46_dialog_content = "... Oof!",
  ui_story_5061_50610602_47_dialog_content = "That didn't hurt as much as I thought it would.",
  ui_story_5061_50610602_48_dialog_content = "(No... It felt as though something caught us as we were falling...)",
  ui_story_5061_50610602_49_dialog_content = "...",
  ui_story_5061_50610602_50_dialog_content = "(That way, it looks safe enough, right?)",
  ui_story_5061_50610602_51_dialog_content = "Hey, Zarya, we should...",
  ui_story_5061_50610602_52_dialog_content = "Oh no, she's out cold...",
  ui_story_5061_50610701_1_dialog_content = "Zarya, stay at home today, don't go anywhere, okay?",
  ui_story_5061_50610701_2_dialog_content = "But I haven't left the house for days now...",
  ui_story_5061_50610701_3_dialog_content = "Why do you always wanna go out? You don't have any buddies or family to watch over you. Or are you planning to cause trouble with your Luminatics again?",
  ui_story_5061_50610701_4_dialog_content = "Remember how you froze the carriage the last time? Such things can never happen again!",
  ui_story_5061_50610701_5_dialog_content = "I... I understand. I'm sorry, Father.",
  ui_story_5061_50610701_6_dialog_content = "(Another lonely day in my room...)",
  ui_story_5061_50610701_7_dialog_content = "Oh, Zarya, check out these flowers—wait, why do you look so down?",
  ui_story_5061_50610701_8_dialog_content = "Alina... Father won't let me leave the house again today...",
  ui_story_5061_50610701_9_dialog_content = "... Father's just too busy with his work to worry about anything else, Zarya.",
  ui_story_5061_50610701_10_dialog_content = "He's scared that he won't be there to help if something happens to you. He doesn't know how else to protect you.",
  ui_story_5061_50610701_11_dialog_content = "I know... It's all because I can't control my Luminatics. I'm nothing but a problem...",
  ui_story_5061_50610701_12_dialog_content = "That's not true, Zarya. Besides, I used to have the same problem too. I would even freeze the front door by accident!",
  ui_story_5061_50610701_13_dialog_content = "I didn't want anyone to find out, which is why I would always kick it open first! Hahaha!",
  ui_story_5061_50610701_14_dialog_content = "Pfft, you can't fool me, Alina. What kind of patrol captain can't control her own powers?",
  ui_story_5061_50610701_15_dialog_content = "Of course I can control them now, but you're a lot more powerful than I was at your age.",
  ui_story_5061_50610701_16_dialog_content = "In fact, with gifts like yours, you could even become a royal guard in Queen Bethlehem's court!",
  ui_story_5061_50610701_17_dialog_content = "A royal guard...? But that's always been your dream, Alina...",
  ui_story_5061_50610701_18_dialog_content = "But being a patroller is great too! I can see all kinds of faraway places, like snowy mountains and even hot springs...",
  ui_story_5061_50610701_19_dialog_content = "And that can't be much worse than serving in the Court, right?",
  ui_story_5061_50610701_20_dialog_content = "You're incredible, Alina... You're always so full of strength and motivation, unlike your useless, depressed sister.",
  ui_story_5061_50610701_21_dialog_content = "Don't worry, Zarya! You'll be just as strong as I am soon enough... No, even stronger!",
  ui_story_5061_50610701_22_dialog_content = "Besides, I still haven't given up on my dream. I'm positive I'll become a royal guard someday!",
  ui_story_5061_50610701_23_dialog_content = "And when that day comes, I'll protect Northland with the Queen!",
  ui_story_5061_50610701_24_dialog_content = "Heehee! I know you can do it!",
  ui_story_5061_50610701_25_dialog_content = "Uh-oh! Looks like I stayed to chat a little too long. It's almost time to meet with the other patrollers!",
  ui_story_5061_50610701_26_dialog_content = "Oh no! You'd better hurry, Alina... Good luck with your mission!",
  ui_story_5061_50610701_27_dialog_content = "Thanks. Try to keep your chin up, okay? Remember, when Father's upset, don't take anything he says too seriously!",
  ui_story_5061_50610701_28_dialog_content = "(... And then she was gone...)",
  ui_story_5061_50610701_29_dialog_content = "(If I knew what happened next... I never would have let her leave.)",
  ui_story_5061_50610701_30_dialog_content = "(... But the past can never be changed. In my sadness and regret, all I could do was risk my life to make things right...)",
  ui_story_5061_50610701_31_dialog_content = "(The last known location of her patrol team... was already swarming with Eclipsites...)",
  ui_story_5061_50610701_32_dialog_content = "Alina! Are you out there?!",
  ui_story_5061_50610701_33_dialog_content = "Roaaar—",
  ui_story_5061_50610701_34_dialog_content = "Stay out of my way!",
  ui_story_5061_50610701_35_dialog_content = "Alina! Please, answer me!",
  ui_story_5061_50610701_36_dialog_content = "Grrrr!",
  ui_story_5061_50610701_37_dialog_content = "Move!",
  ui_story_5061_50610701_38_dialog_content = "Sister... Are you... Still alive? I'm so scared...",
  ui_story_5061_50610701_39_dialog_content = "... No need... to fear.",
  ui_story_5061_50610701_40_dialog_content = "...!",
  ui_story_5061_50610701_41_dialog_content = "That voice... Is that you, Alina?",
  ui_story_5061_50610701_42_dialog_content = "... Do you want to save someone?",
  ui_story_5061_50610701_43_dialog_content = "Yes! I... I want to save my sister!",
  ui_story_5061_50610701_44_dialog_content = "... I acknowledge your potential...",
  ui_story_5061_50610701_45_dialog_content = "... With you, perhaps the mission... could be accomplished...",
  ui_story_5061_50610701_46_dialog_content = "... In that case, you will take over... my solitude...",
  ui_story_5061_50610701_47_dialog_content = "(And so, I followed that voice through the snow...)",
  ui_story_5061_50610701_48_dialog_content = "(I thought it would lead me to my sister, but instead... It led me to a hell that I never could have imagined.)",
  ui_story_5061_50610701_49_dialog_content = "<color=#e8d9bb>Countless patrollers were lying motionless on the ground.</color>",
  ui_story_5061_50610701_50_dialog_content = "<color=#e8d9bb>Eclipsites with gaping maws and a cacophony of roars.</color>",
  ui_story_5061_50610701_51_dialog_content = "<color=#e8d9bb>The nauseating stench, still piercing even amidst the swirling snow.</color>",
  ui_story_5061_50610701_52_dialog_content = "<color=#e8d9bb>And the abyss-like, viscous, repugnant quagmire on the ground.</color>",
  ui_story_5061_50610701_53_dialog_content = "This isn't real... This can't be real...",
  ui_story_5061_50610701_54_dialog_content = "You filthy monsters! Stay away from my sister!",
  ui_story_5061_50610701_55_dialog_content = "Bloom, Frostlight!",
  ui_story_5061_50610701_56_dialog_content = "Roaaar—",
  ui_story_5061_50610701_57_dialog_content = "There are too many of them! I can't beat them all!",
  ui_story_5061_50610701_58_dialog_content = "Roaaaaaaar—",
  ui_story_5061_50610701_59_dialog_content = "I'm sorry, Alina... I don't think I can kill all of these Eclipsites!",
  ui_story_5061_50610701_60_dialog_content = "If only I were stronger, then maybe I could save you now...",
  ui_story_5061_50610701_61_dialog_content = "Alina... Alina! Nooooooo!!!",
  ui_story_5061_50610701_62_dialog_content = "<size=45>Alina!!!</size>",
  ui_story_5061_50610701_63_dialog_content = "... Zarya! Wake up!",
  ui_story_5061_50610701_64_dialog_content = "Alina!",
  ui_story_5061_50610701_65_dialog_content = "Calm down, Zarya! It was just a nightmare!",
  ui_story_5061_50610701_66_dialog_content = "...",
  ui_story_5061_50610701_67_dialog_content = "Do you remember the ground giving out from under us? I think we fell into a cave of some sort.",
  ui_story_5061_50610701_68_dialog_content = "There seem to be ruins trapped in the ice down here. I'm gonna take a closer look...",
  ui_story_5061_50610701_69_dialog_content = "Roaaar—",
  ui_story_5061_50610701_70_dialog_content = "Ah! E-Eclipsites! Oh no, what should we do? I can't beat them all...",
  ui_story_5061_50610701_71_dialog_content = "Why are you panicking? Does this have something to do with your nightmare?",
  ui_story_5061_50610701_72_dialog_content = "Get it together, Zarya! Don't let the past get in the way of your present!",
  ui_story_5061_50610701_73_dialog_content = "Roaaar—",
  ui_story_5061_50610701_74_dialog_content = "Where's the Zarya we knew?! We need her now more than ever!",
  ui_story_5061_50610701_75_dialog_content = "Energy—Absorption! Hurry, this way!",
  ui_story_5061_50610701_76_dialog_content = "That voice...!",
  ui_story_5061_50610701_77_dialog_content = "Get up, Zarya! We need to get out of here!",
  ui_story_5061_50610702_1_dialog_content = "We should be safe here for now.",
  ui_story_5061_50610702_2_dialog_content = "I've been exploring this area for some time now. If my hunch is correct, there should be another exit nearby, one that leads to the rest of the underground ruins of Northland.",
  ui_story_5061_50610702_3_dialog_content = "Those exits are usually the most dangerous when it comes to these ruins.",
  ui_story_5061_50610702_4_dialog_content = "The Eclipsites around them are starting to thaw out. They can wake up any second now.",
  ui_story_5061_50610702_5_dialog_content = "This ice... It's made from the same Luminatics as Zarya's, isn't it?",
  ui_story_5061_50610702_6_dialog_content = "That's right. In fact, I have reason to believe that it was also produced by Miss Zarya herself.",
  ui_story_5061_50610702_7_dialog_content = "It was most likely the explosive result of her power going out of control in the past.",
  ui_story_5061_50610702_8_dialog_content = "You're saying... that I did this?",
  ui_story_5061_50610702_9_dialog_content = "I can't think of a better answer at the moment, so yes.",
  ui_story_5061_50610702_10_dialog_content = "To tell the truth, Miss Zarya... I've wanted to ask you something for a long time now, but I haven't been able to find the right words...",
  ui_story_5061_50610702_11_dialog_content = "Does it have something to do with our current situation?",
  ui_story_5061_50610702_12_dialog_content = "Please speak your mind, Mr. Antony. This is the second time you've saved my life now; answering your questions is the least I can do.",
  ui_story_5061_50610702_13_dialog_content = "If your kindness isn't enough to make me accept the truth...",
  ui_story_5061_50610702_14_dialog_content = "Then I don't know what will.",
  ui_story_5061_50610702_15_dialog_content = "Very well. Let's start with the source of your power.",
  ui_story_5061_50610702_16_dialog_content = "I think I have a basic understanding of it now. The strange Lumina present in your body originated in these ruins, and it appears you were granted this power for some unknown purpose.",
  ui_story_5061_50610702_17_dialog_content = "To prove my point... PlayerName, would you be so kind as to use your own powers to scan the ice in these ruins?",
  ui_story_5061_50610702_18_dialog_content = "Uh... Sure!",
  ui_story_5061_50610702_19_option_content = "Psychic Scan",
  ui_story_5061_50610702_20_dialog_content = "These ice formations... They were definitely influenced by Luminatics.",
  ui_story_5061_50610702_21_dialog_content = "Hmm? They're even emitting Lumina particles!",
  ui_story_5061_50610702_22_dialog_content = "This feeling... It's no different than when I sensed the ice around Zarya when we first met.",
  ui_story_5061_50610702_23_dialog_content = "You're right! And when I get closer to take a look...",
  ui_story_5061_50610702_24_dialog_content = "Zarya, your hair...!",
  ui_story_5061_50610702_25_dialog_content = "Huh? Why is my hair suddenly glowing...?",
  ui_story_5061_50610702_26_dialog_content = "It's a type of resonance, I believe. When PlayerName used his powers on the ice, it started to resonate with the Lumina in your body.",
  ui_story_5061_50610702_27_dialog_content = "But isn't that dangerous?",
  ui_story_5061_50610702_28_dialog_content = "I can't be sure... But the potential danger is nothing compared to what I'm about to say.",
  ui_story_5061_50610702_29_dialog_content = "What is it...?",
  ui_story_5061_50610702_30_dialog_content = "When we were still on the surface, I based my conjecture on the recent phenomenon known as the Aurorastorm...",
  ui_story_5061_50610702_31_dialog_content = "As such, it was impossible for me to establish a timeline for the incident described by Miss Zarya. In fact, I couldn't even prove that it had ever happened.",
  ui_story_5061_50610702_32_dialog_content = "However, by using Miss Zarya's testimony as the basis for my conjecture...",
  ui_story_5061_50610702_33_dialog_content = "I quickly stumbled across a startling discovery.",
  ui_story_5061_50610702_34_dialog_content = "Namely, Miss Zarya's sister, a former patroller captain and an honorary member of the Northland royal guard known as <color=#FFB400>Alina</color>...",
  ui_story_5061_50610702_35_dialog_content = "Was a prominent figure who lived <color=#FFB400>many decades ago</color>!",
  ui_story_5061_50610702_36_dialog_content = "...",
  ui_story_5061_50610702_37_dialog_content = "In other words, the Aurorastorm you experienced was the same event from <color=#FFB400>a hundred years ago</color>.",
  ui_story_5061_50610702_38_dialog_content = "... What?",
  ui_story_5061_50610702_39_dialog_content = "But...",
  ui_story_5061_50610702_40_dialog_content = "But that means... <size=45>Zarya is <color=#FFB400>over a hundred years old</color>???</size>",
  ui_story_5061_50610801_1_dialog_content = "He owns more books than a library... Wait, what's a \"ready-o\"?",
  ui_story_5061_50610801_2_dialog_content = "PlayerName? It also mentions something called a \"transmitter function.\" What does that mean?",
  ui_story_5061_50610801_3_dialog_content = "Geez, why you talkin' like my grandma? Nobody scares kids like that these days!",
  ui_story_5061_50610801_4_dialog_content = "In fact, it feels like you were stuck in the ice for a really long time.",
  ui_story_5061_50610801_5_dialog_content = "(... I finally understand why things seemed so off now!)",
  ui_story_5061_50610801_6_dialog_content = "(Even though things hardly change here in Northland, time is still just as unforgiving as anywhere else...",
  ui_story_5061_50610801_7_dialog_content = "(A hundred years passed while Zarya was frozen in the ice...)",
  ui_story_5061_50610801_8_dialog_content = "...",
  ui_story_5061_50610801_9_dialog_content = "No... This can't be...",
  ui_story_5061_50610801_10_dialog_content = "You must be joking, right, Mr. Antony?",
  ui_story_5061_50610801_11_dialog_content = "I'm sorry, but this is the truth.",
  ui_story_5061_50610801_12_dialog_content = "The truth...?",
  ui_story_5061_50610801_13_dialog_content = "So the truth... is that this world is a century past my own time?",
  ui_story_5061_50610801_14_dialog_content = "All of my loved ones... my sister... They're all gone now?",
  ui_story_5061_50610801_15_dialog_content = "And I'm... the only one left?",
  ui_story_5061_50610801_16_dialog_content = "Zarya...",
  ui_story_5061_50610801_17_dialog_content = "...",
  ui_story_5061_50610801_18_dialog_content = "... I don't believe you!",
  ui_story_5061_50610801_19_dialog_content = "Wait, Zarya! Where are you going?",
  ui_story_5061_50610801_20_dialog_content = "Don't bother following me!",
  ui_story_5061_50610801_21_dialog_content = "What? I can't just leave you alone in here!",
  ui_story_5061_50610801_22_dialog_content = "Do you have any idea how I feel right now? Please, just don't say another word...",
  ui_story_5061_50610801_23_dialog_content = "Sorry, Zarya, but you have to listen to me! I know exactly how you feel!",
  ui_story_5061_50610801_24_dialog_content = "I know how it feels to be left alone in a cold, dark place!",
  ui_story_5061_50610801_25_dialog_content = "I know how hard it is to reappear in the world, only to find out that everyone's forgotten about you!",
  ui_story_5061_50610801_26_dialog_content = "And... I know how painful it is to finally learn more about your past, only to find yourself back where you first started.",
  ui_story_5061_50610801_27_dialog_content = "...",
  ui_story_5061_50610801_28_dialog_content = "I... I knew there was something wrong from the very beginning...",
  ui_story_5061_50610801_29_dialog_content = "... But I don't want to accept this! You may be right about my new powers not being my own...",
  ui_story_5061_50610801_30_dialog_content = "After all, I'm just a coward who makes everything worse...",
  ui_story_5061_50610801_31_dialog_content = "If only I were as brave as you...",
  ui_story_5061_50610801_32_dialog_content = "If only I were as strong... As you or my sister... Sniff...",
  ui_story_5061_50610801_33_dialog_content = "Waaaaaaah—",
  ui_story_5061_50610801_34_dialog_content = "(Zarya...)",
  ui_story_5061_50610801_35_option_content = "Put a hand on her shoulder",
  ui_story_5061_50610801_36_option_content = "Hug her gently",
  ui_story_5061_50610801_37_dialog_content = "(... You're not alone.)",
  ui_story_5061_50610801_38_dialog_content = "You have us now, Zarya... We're here for you too.",
  ui_story_5061_50610801_39_dialog_content = "Whenever you're feeling down, just remember... There's at least one other person in the world who knows what it feels like to be abandoned by time.",
  ui_story_5061_50610801_40_dialog_content = "Someone who still runs into all kinds of problems with reintegrating into society...",
  ui_story_5061_50610801_41_dialog_content = "I...",
  ui_story_5061_50610801_42_dialog_content = "Someone who, despite having incredible powers, still gets his legs frozen when he tries to help others in need.",
  ui_story_5061_50610801_43_dialog_content = "<color=#e8d9bb>Rumble—!!!</color>",
  ui_story_5061_50610801_44_dialog_content = "...! What the heck was that?!",
  ui_story_5061_50610801_45_dialog_content = "An abnormal growth in the ice is causing this part of the cave to collapse!",
  ui_story_5061_50610801_46_dialog_content = "No... This is far too intense to simply describe as \"abnormal.\" The resonance between Zarya and the ice may be the cause of it...",
  ui_story_5061_50610801_47_dialog_content = "Though it could also be caused by the ruins...",
  ui_story_5061_50610801_48_dialog_content = "We need to reach the exit as soon as possible! We can find it by following the flow of air!",
  ui_story_5061_50610801_49_dialog_content = "Can you stand, Zarya? We have to get going!",
  ui_story_5061_50610801_50_dialog_content = "I... I'm fine!",
  ui_story_5061_50610801_51_dialog_content = "This way, PlayerName!",
  ui_story_5061_50610801_52_dialog_content = "Even the ruins are starting to shake. This place is gonna come crashing down any second now!",
  ui_story_5061_50610801_53_dialog_content = "<color=#e8d9bb>Thud!</color>",
  ui_story_5061_50610801_54_dialog_content = "Urg, my leg!",
  ui_story_5061_50610801_55_dialog_content = "You're hurt!",
  ui_story_5061_50610801_56_dialog_content = "I-It's just a scratch, don't worry! I can still run!",
  ui_story_5061_50610801_57_dialog_content = "I can see the light through the cave's ceiling over here! We're almost to the exit, now hurry!",
  ui_story_5061_50610801_58_dialog_content = "<color=#e8d9bb>Crack!</color>",
  ui_story_5061_50610801_59_dialog_content = "Watch your head, PlayerName!",
  ui_story_5061_50610801_60_dialog_content = "(A massive chunk of ice is falling down above me. The pain in my leg tells me that I won't be able to dodge it in time...)",
  ui_story_5061_50610801_61_dialog_content = "(At the very least... I have to help those two escape...)",
  ui_story_5061_50610801_62_option_content = "Shove Zarya",
  ui_story_5061_50610801_63_dialog_content = "Look out, Zarya!",
  ui_story_5061_50610801_64_option_content = "Shove Antony",
  ui_story_5061_50610801_65_dialog_content = "Look out, Antony!",
  ui_story_5061_50610801_66_dialog_content = "... Bloom, Frostlight!",
  ui_story_5061_50610801_67_dialog_content = "<color=#e8d9bb>Under Zarya's attack, the massive rock shattered into small pieces and scattered around.</color>",
  ui_story_5061_50610801_68_dialog_content = "Zarya... You saved us!",
  ui_story_5061_50610801_69_dialog_content = "I know... I know that if my sister were here right now, she wouldn't want me to keep wallowing in my sadness...",
  ui_story_5061_50610801_70_dialog_content = "That's why I'm going to use my Luminatics on this ice, and break open a path for you.",
  ui_story_5061_50610801_71_dialog_content = "I'll leave the navigation to you! If you spot any Eclipsites, tell me where they are and I'll do what I can!",
  ui_story_5061_50610801_72_dialog_content = "Got it!",
  ui_story_5061_50610801_73_dialog_content = "Understood. Our goal is the surface!",
  ui_story_5061_50610802_1_dialog_content = "We're already far outside of the Beacon's protective range. Heading towards the exit will also lead us in the opposite direction of the Beacon.",
  ui_story_5061_50610802_2_dialog_content = "From here on out, I'm afraid the Eclipsites are only going to grow in strength and numbers.",
  ui_story_5061_50610802_3_dialog_content = "...!",
  ui_story_5061_50610802_4_dialog_content = "I... I feel something nearby.",
  ui_story_5061_50610802_5_dialog_content = "More Eclipsites?",
  ui_story_5061_50610802_6_dialog_content = "No, that's not it.",
  ui_story_5061_50610802_7_dialog_content = "I sensed a presence when we were still on the surface. From what I can tell... It might be an Aurorian.",
  ui_story_5061_50610802_8_dialog_content = "An Aurorian? In a place like this?",
  ui_story_5061_50610802_9_dialog_content = "Yes, it's definitely an Aurorian, but something feels different.",
  ui_story_5061_50610802_10_dialog_content = "Let me try using my powers again...",
  ui_story_5061_50610802_11_option_content = "Psychic Scan",
  ui_story_5061_50610802_12_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610802_13_dialog_content = "It's been so many years. You have forgotten about me for all these years.",
  ui_story_5061_50610802_14_dialog_content = "Now, suddenly reappearing like this, what for? For the power of the <color=#FFB400>Spark</color>?",
  ui_story_5061_50610802_15_dialog_content = "A century has elapsed. Why do I, being activated again, lack energy so much while you all are so... full?",
  ui_story_5061_50610802_16_dialog_content = "Urgh... M-My head...",
  ui_story_5061_50610802_17_dialog_content = "What... Are you talking about...?",
  ui_story_5061_50610802_18_dialog_content = "Answer me, Aurorians of the land, willing conduits of Lux—receivers of the Spark's blessing!",
  ui_story_5061_50610802_19_dialog_content = "Ahh!!!",
  ui_story_5061_50610802_20_dialog_content = "(My head's splitting in two... I need to break off the link!)",
  ui_story_5061_50610802_21_dialog_content = "Wait, Miss Zarya!",
  ui_story_5061_50610802_22_dialog_content = "Are you alright, PlayerName? Can you still see me? What about this? Can you feel me pinching your fingers?",
  ui_story_5061_50610802_23_dialog_content = "Hmmm... Yes, I can feel you.",
  ui_story_5061_50610802_24_dialog_content = "Good, your reaction is normal and your vision seems fine. It doesn't look like you hurt your head either...",
  ui_story_5061_50610802_25_dialog_content = "I'm fine, let's keep moving. I felt a dangerous Aurorian just now... Wait, she...",
  ui_story_5061_50610802_26_dialog_content = "<size=45>... She's coming!!</size>",
  ui_story_5061_50610802_27_dialog_content = "<color=#e8d9bb>Zoom!</color>",
  ui_story_5061_50610802_28_dialog_content = "Urgh! M-My body...",
  ui_story_5061_50610802_29_dialog_content = "What is this? I... I can't control the flow of my Lumina!",
  ui_story_5061_50610802_30_dialog_content = "My body feels so heavy...",
  ui_story_5061_50610802_31_dialog_content = "It's taking all my strength just to stand up...",
  ui_story_5061_50610802_32_dialog_content = "Hang on...",
  ui_story_5061_50610802_33_dialog_content = "Your Lumina... And even the Lumina of the ruins... It's all being sucked towards the same direction!",
  ui_story_5061_50610901_1_dialog_content = "<color=#e8d9bb>At the endpoint of the Lumina flow, a figure in pristine white emerges.</color>",
  ui_story_5061_50610901_2_dialog_content = "<color=#e8d9bb>Her body hovers in the center of space, radiating an ethereal sense of weightlessness, with the heavenly light at the exit serving as her backdrop.</color>",
  ui_story_5061_50610901_3_dialog_content = "<color=#e8d9bb>As she gracefully moves those intricate mechanical limbs, the entire ruin seems to awaken, emitting brilliance and resonating with her.</color>",
  ui_story_5061_50610901_4_dialog_content = "Here you are.",
  ui_story_5061_50610901_5_dialog_content = "Are you... An Aurorian?",
  ui_story_5061_50610901_6_dialog_content = "I'm... the ruins' manager and guardian, No. 33.",
  ui_story_5061_50610901_7_dialog_content = "To fulfill the mission, energy retrieval is necessary.",
  ui_story_5061_50610901_8_dialog_content = "Your actions... have breached the defense boundaries.",
  ui_story_5061_50610901_9_dialog_content = "Your manner of speaking...",
  ui_story_5061_50610901_10_dialog_content = "What, Caelestite, do you intend to employ your powers on me, which will trigger my defensive counterattack?",
  ui_story_5061_50610901_11_dialog_content = "(That feeling of having my mind pierced... Was that her \"defensive counterattack\"?)",
  ui_story_5061_50610901_12_dialog_content = "Be careful, PlayerName. I can sense that something's wrong with her.",
  ui_story_5061_50610901_13_dialog_content = "It's as if... something about her is broken.",
  ui_story_5061_50610901_14_dialog_content = "Ah, you, the girl with special Lumina powers. You have caused me quite a lot of trouble...",
  ui_story_5061_50610901_15_dialog_content = "Me? What did I do?",
  ui_story_5061_50610901_16_dialog_content = "As the backup power block for the <color=#FFB400>Spark</color>...",
  ui_story_5061_50610901_17_dialog_content = "Here, the Lumina flow order, smooth and uninterrupted, is crucial!",
  ui_story_5061_50610901_18_dialog_content = "Your strong absorption ability disrupts the whole system, making my repair work fail again and again.",
  ui_story_5061_50610901_19_dialog_content = "... Absorption ability?",
  ui_story_5061_50610901_20_dialog_content = "I see. That may explain why your hair changed colors, Miss Zarya.",
  ui_story_5061_50610901_21_dialog_content = "But if you're the guardian of this place, why are there Eclipsites roaming freely everywhere?",
  ui_story_5061_50610901_22_dialog_content = "\"Everywhere\"? There is no such concept. I only have \"here.\"",
  ui_story_5061_50610901_23_dialog_content = "Connected to me, this facility is my all...",
  ui_story_5061_50610901_24_dialog_content = "My mission... is to <color=#FFB400>maintain the Lumina balance here</color>. Everything else is unrelated.",
  ui_story_5061_50610901_25_dialog_content = "What are you planning to do?",
  ui_story_5061_50610901_26_dialog_content = "It's none of your concern, outsider. I need to eliminate her and recover the Lumina she stole...",
  ui_story_5061_50610901_27_dialog_content = "The Lumina... I stole? What do you mean by that?",
  ui_story_5061_50610901_28_dialog_content = "Command: Destroy.",
  ui_story_5061_50610901_29_dialog_content = "Careful!",
  ui_story_5061_50610901_30_dialog_content = "Stop! We can still talk things out!",
  ui_story_5061_50610901_31_dialog_content = "Too late... It's been too long...",
  ui_story_5061_50610901_32_dialog_content = "I won't waste my time expecting... and trying.",
  ui_story_5061_50610901_33_dialog_content = "Since you won't comply with my instructions, I can only resort to the use of force...",
  ui_story_5061_50610901_34_dialog_content = "Prepare for battle, everyone!",
  ui_story_5061_50610902_1_dialog_content = "... Cover, Frost Edge!",
  ui_story_5061_50610902_2_dialog_content = "Environmental Assault!",
  ui_story_5061_50610902_3_dialog_content = "Our attacks aren't strong enough!",
  ui_story_5061_50610902_4_dialog_content = "We can't hurt her while our Lumina is being drained from our bodies...",
  ui_story_5061_50610902_5_dialog_content = "Watch out, PlayerName! She's attacking!",
  ui_story_5061_50610902_6_dialog_content = "Urgh! ... I've got you.",
  ui_story_5061_50610902_7_dialog_content = "Antony!",
  ui_story_5061_50610902_8_dialog_content = "Don't worry about me. My Lumina may not be as powerful as Miss Zarya's, but my physical strength is dependable enough.",
  ui_story_5061_50610902_9_dialog_content = "(... Is there really no other way?)",
  ui_story_5061_50610902_10_dialog_content = "(They've been protecting me all this time... Is there really nothing I can do to help?)",
  ui_story_5061_50610902_11_dialog_content = "(Maybe if I try using my powers again... I'll be able to find her weak point!)",
  ui_story_5061_50610902_12_option_content = "Force Boost",
  ui_story_5061_50610902_13_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610902_14_dialog_content = "Urgh—My head!",
  ui_story_5061_50610902_15_dialog_content = "Stop it, PlayerName!",
  ui_story_5061_50610902_16_dialog_content = "Her mind is protected from your psychic powers! You'll only hurt yourself if you use them!",
  ui_story_5061_50610902_17_dialog_content = "I-I can't just let you guys do all the fighting... Which is why I'm gonna help you the only way I can...",
  ui_story_5061_50610902_18_option_content = "Force Boost",
  ui_story_5061_50610902_19_dialog_content = "If there's a way around her defenses, then maybe I can—",
  ui_story_5061_50610902_20_dialog_content = "Argh...! My head's about to burst!",
  ui_story_5061_50610902_21_dialog_content = "Drat... Even if I hold him down, I cannot stop PlayerName from using his powers.",
  ui_story_5061_50610902_22_dialog_content = "That's enough! Just stop!",
  ui_story_5061_50610902_23_dialog_content = "You can't just keep hurting yourself like this, PlayerName!",
  ui_story_5061_50610902_24_dialog_content = "That goes for you too, Mr. Antony!",
  ui_story_5061_50610902_25_dialog_content = "I... I owe my life to the two of you. I can't stand to see you get hurt anymore.",
  ui_story_5061_50610902_26_dialog_content = "You're good people, and you still have goals to pursue in life.",
  ui_story_5061_50610902_27_dialog_content = "Wait, Zarya, what do you mean by that...?",
  ui_story_5061_50610902_28_dialog_content = "I've lost my sister, my family, and the life I used to have...",
  ui_story_5061_50610902_29_dialog_content = "I have nowhere to go anymore, no place to call \"home\"... I'm just an empty shell of the person I once was.",
  ui_story_5061_50610902_30_dialog_content = "Which is why I don't care what happens to me now.",
  ui_story_5061_50610902_31_dialog_content = "But at least you two—",
  ui_story_5061_50610902_32_dialog_content = "What the hell do you think you're doing, Zarya?!",
  ui_story_5061_50610902_33_dialog_content = "<color=#e8d9bb>Crunch—</color>",
  ui_story_5061_50610902_34_dialog_content = "Wait, Zarya—!",
  ui_story_5061_50610902_35_dialog_content = "You must live.",
  ui_story_5061_50610902_36_dialog_content = "Zarya!!!",
  ui_story_5061_50610902_37_dialog_content = "<size=45>Zaryaaaaaaaa!!!</size>",
  ui_story_5061_50611001_1_dialog_content = "(Zarya used a pillar of ice to deliver us safely outside...)",
  ui_story_5061_50611001_2_dialog_content = "(Shortly afterward, the cave exit completely collapsed.)",
  ui_story_5061_50611001_3_dialog_content = "Why... Why didn't I notice it sooner?!",
  ui_story_5061_50611001_4_dialog_content = "No... This can't be...",
  ui_story_5061_50611001_5_dialog_content = "If only I were as strong... As you or my sister... Sniff...",
  ui_story_5061_50611001_6_dialog_content = "Waaaaaaaaaaah—",
  ui_story_5061_50611001_7_dialog_content = "You must live.",
  ui_story_5061_50611001_8_dialog_content = "If only I were as strong as you...",
  ui_story_5061_50611001_9_dialog_content = "The moment Zarya learned the truth, she lost all hope in her heart.",
  ui_story_5061_50611001_10_dialog_content = "She hardly said a word after that. She just followed us as we ran and fought our way out...",
  ui_story_5061_50611001_11_dialog_content = "I'm sorry. I should have noticed something was amiss as well.",
  ui_story_5061_50611001_12_dialog_content = "She's all alone in there, trapped in the ruins with no way out... And that's exactly what she wants.",
  ui_story_5061_50611001_13_dialog_content = "... We need to go back and save her, but how? I can't fight like you guys, and my psychic powers only backfire on me.",
  ui_story_5061_50611001_14_dialog_content = "Not only that... No. 33 will just drain your Lumina if we fight her again! What should we do?!",
  ui_story_5061_50611001_15_dialog_content = "At least for the time being, we can trust that Miss Zarya's strength won't fail her anytime soon. She won't go down without a fight.",
  ui_story_5061_50611001_16_dialog_content = "Even while her Lumina was being drained in battle, she still had enough to generate a pillar of ice to bring us to safety.",
  ui_story_5061_50611001_17_dialog_content = "Also... Someone willing to venture into a dangerous place on their own won't give up their life so easily.",
  ui_story_5061_50611001_18_dialog_content = "So, is there anything we can do to help Zarya right now?",
  ui_story_5061_50611001_19_dialog_content = "...There is.",
  ui_story_5061_50611001_20_dialog_content = "This place is far beyond Northland's northwestern border, but with your help, we should be fine.",
  ui_story_5061_50611001_21_dialog_content = "What do you need me to do?",
  ui_story_5061_50611001_22_dialog_content = "I need you to find the closest rabbit to us.",
  ui_story_5061_50611001_23_dialog_content = "A rabbit?",
  ui_story_5061_50611001_24_dialog_content = "Correct. It's a fluffy, white animal about this big, with long ears and—",
  ui_story_5061_50611001_25_dialog_content = "I know what a rabbit is, Antony. I just don't know why you need one right now.",
  ui_story_5061_50611001_26_dialog_content = "Oh, you do? Then you shouldn't have trouble finding one!",
  ui_story_5061_50611001_27_dialog_content = "There should be one to the southeast... But I can't tell how far it is. Think you could give me a hand?",
  ui_story_5061_50611001_28_dialog_content = "(... Guess I'll just have to do as he says for now.)",
  ui_story_5061_50611001_29_option_content = "Force Boost",
  ui_story_5061_50611001_30_dialog_content = "(To the southeast, huh? Wait... Didn't Zarya and I see a rabbit on the way here?)",
  ui_story_5061_50611001_31_dialog_content = "(... We did! And it's right over there!)",
  ui_story_5061_50611001_32_dialog_content = "(The rabbit seems to have noticed something too. It's looking in our direction.)",
  ui_story_5061_50611001_33_dialog_content = "I found one, Antony.",
  ui_story_5061_50611001_34_dialog_content = "R-Really? That was fast! Your psychic abilities are really something else!",
  ui_story_5061_50611001_35_dialog_content = "Heh... They're alright, I guess...",
  ui_story_5061_50611001_36_dialog_content = "Anyway, we should get going.",
  ui_story_5061_50611001_37_dialog_content = "Over here!",
  ui_story_5061_50611001_38_dialog_content = "Excellent! If I'm not mistaken, this rabbit is one of <color=#FFB400>his</color> companions.",
  ui_story_5061_50611001_39_dialog_content = "Hello, my little friend! Could you help us send a message to your master, the <color=#FFB400>mountain spirit</color>? Please tell him that we found a forgotten set of ruins here, as well as a long-lost citizen of Northland.",
  ui_story_5061_50611001_40_dialog_content = "<color=#e8d9bb>The rabbit hops far, far away in the direction of Northland.</color>",
  ui_story_5061_50611001_41_dialog_content = "A \"forgotten set of ruins\"... Do you think it has something to do with the \"<color=#FFB400>Spark</color>\" that Aurorian mentioned earlier?",
  ui_story_5061_50611001_42_dialog_content = "I believe so. If what she says is true, these ruins serve as a power supply for the Spark.",
  ui_story_5061_50611001_43_dialog_content = "The Spark, in turn, powers our kingdom's defenses. As such, these ruins are the most important in all of Northland.",
  ui_story_5061_50611001_44_dialog_content = "The <color=#FFB400>Beacon</color>, which projects the barrier that protects our entire kingdom from Eclipsites, is also part of the Spark.",
  ui_story_5061_50611001_45_dialog_content = "Does that mean the crazy guardian we ran into is also part of Northland's defenses?",
  ui_story_5061_50611001_46_dialog_content = "I believe only the Queen and the mountain spirit are privy to that knowledge.",
  ui_story_5061_50611002_1_dialog_content = "I'll never give up!",
  ui_story_5061_50611002_2_dialog_content = "(I don't have enough Lumina to hurt her...)",
  ui_story_5061_50611002_3_dialog_content = "(Also... Not only does she look different from other Aurorians, but her actions and speech patterns are really strange as well...)",
  ui_story_5061_50611002_4_dialog_content = "I've been meaning to ask you something...",
  ui_story_5061_50611002_5_dialog_content = "Why... Why does your voice sound just like my sister's?!",
  ui_story_5061_50611002_6_dialog_content = "My voice...",
  ui_story_5061_50611002_7_dialog_content = "Miss Alina's voice...",
  ui_story_5061_50611002_8_dialog_content = "You know who she is?! Tell me, what have you done to my sister?!",
  ui_story_5061_50611002_9_dialog_content = "Met her in person... Made a temporary pact...",
  ui_story_5061_50611002_10_dialog_content = "Became an energy vessel to execute the maximum clearance protocol and disperse the Eclipsites...",
  ui_story_5061_50611002_11_dialog_content = "...What do you mean?",
  ui_story_5061_50611002_12_dialog_content = "Alina was here once... and she found me.",
  ui_story_5061_50611002_13_dialog_content = "The outside was swarming with Eclipsites, and her energy was depleted... I cannot leave...",
  ui_story_5061_50611002_14_dialog_content = "A dire situation. Alina, she took in all the energy here and became the vessel. The only solution...",
  ui_story_5061_50611002_15_dialog_content = "So in order to defeat the Eclipsites... You turned my sister into a vessel for the Lumina of these ruins?",
  ui_story_5061_50611002_16_dialog_content = "But an Aurorian's body can't possibly contain that much Lumina... Can it?",
  ui_story_5061_50611002_17_dialog_content = "Cannot... She knew she would sacrifice her life. No way around it.",
  ui_story_5061_50611002_18_dialog_content = "... It's fine. We have no other options left.",
  ui_story_5061_50611002_19_dialog_content = "Have you really thought it through?",
  ui_story_5061_50611002_20_dialog_content = "You've protected this place for so long... But now it's time for one of us to protect you.",
  ui_story_5061_50611002_21_dialog_content = "Not only that... But I also want to protect our world for my sister's sake.",
  ui_story_5061_50611002_22_dialog_content = "I admire your courage. Let us begin...",
  ui_story_5061_50611002_23_dialog_content = "Thank you... Spirit of the Aurora. I leave the rest in your hands now.",
  ui_story_5061_50611002_24_dialog_content = "But I...",
  ui_story_5061_50611002_25_dialog_content = "But I hope you can survive.",
  ui_story_5061_50611002_26_dialog_content = "My first surface-dwelling Aurorian friend.",
  ui_story_5061_50611002_27_dialog_content = "Calculation... commencing calculation...",
  ui_story_5061_50611002_28_dialog_content = "The method to ensure your survival...",
  ui_story_5061_50611002_29_dialog_content = "Is that really... how my sister sacrificed herself?",
  ui_story_5061_50611002_30_dialog_content = "... Urgh... Alina... Alina...",
  ui_story_5061_50611002_31_dialog_content = "Error in Echo Template!",
  ui_story_5061_50611002_32_dialog_content = "Attempting to reboot.",
  ui_story_5061_50611002_33_dialog_content = "To protect everyone from the Aurorastorm... to protect me...",
  ui_story_5061_50611101_1_dialog_content = "Error in Echo Template!",
  ui_story_5061_50611101_2_dialog_content = "Reboot, error; reboot, error; reboot—",
  ui_story_5061_50611101_3_dialog_content = "Warning: Intruders detected within the facility;",
  ui_story_5061_50611101_4_dialog_content = "Eliminate, eliminate;",
  ui_story_5061_50611101_5_dialog_content = "What's going on? Hey! We weren't done talking yet!",
  ui_story_5061_50611101_6_dialog_content = "Why is this suddenly happening to you again? Do you need me to cool you off again?!",
  ui_story_5061_50611101_7_dialog_content = "Guarding this place, my sole mission;",
  ui_story_5061_50611101_8_dialog_content = "Everything else, irrelevant, eliminate;",
  ui_story_5061_50611101_9_dialog_content = "What are you talking about?!",
  ui_story_5061_50611101_10_dialog_content = "Didn't you say you protected everyone with my sister's help?",
  ui_story_5061_50611101_11_dialog_content = "Don't tell me you've forgotten?!",
  ui_story_5061_50611101_12_dialog_content = "Template rebooted... Encountered unknown error;",
  ui_story_5061_50611101_13_dialog_content = "Come, everyone.",
  ui_story_5061_50611101_14_dialog_content = "We must descend as lightly as possible...",
  ui_story_5061_50611101_15_dialog_content = "I can see the bottom!",
  ui_story_5061_50611101_16_dialog_content = "Look! It's Miss Zarya!",
  ui_story_5061_50611101_17_dialog_content = "Zarya! We came back to save you!",
  ui_story_5061_50611101_18_dialog_content = "What...? Why? Do you have any idea how hard it was to get you out of here?!",
  ui_story_5061_50611101_19_dialog_content = "I told you before! You're not alone anymore!",
  ui_story_5061_50611101_20_dialog_content = "You... I can't... Ugh, what am I supposed to do with you?!",
  ui_story_5061_50611101_21_dialog_content = "We'll be fine! Besides, we came up with a plan!",
  ui_story_5061_50611101_22_dialog_content = "... A plan?",
  ui_story_5061_50611101_23_dialog_content = "Haven't you noticed that your Lumina isn't draining away anymore?",
  ui_story_5061_50611101_24_dialog_content = "... You're right!",
  ui_story_5061_50611101_25_dialog_content = "Now, all we need to do is limit No. 33's movements.",
  ui_story_5061_50611101_26_dialog_content = "Once we do, I'll wait for the right moment to use my powers on her!",
  ui_story_5061_50611101_27_dialog_content = "Have you gone insane, PlayerName?! Have you already forgotten what that does to you?!",
  ui_story_5061_50611101_28_dialog_content = "No. 33's <color=#FFB400>Echo Template keeps producing errors</color> because of the damage she's sustained, as well as her unorthodox activation.",
  ui_story_5061_50611101_29_dialog_content = "The only one who can repair her Echo Template is PlayerName, and only by using his powers.",
  ui_story_5061_50611101_30_dialog_content = "We also have <color=#FFB400>his</color> protection, so we shouldn't meet with any further resistance.",
  ui_story_5061_50611101_31_dialog_content = "Are you ready, Zarya?",
  ui_story_5061_50611101_32_dialog_content = "... Yes. I believe in you!",
  ui_story_5061_50611101_33_dialog_content = "Let's do this!",
  ui_story_5061_50611102_1_dialog_content = "She's slowing down!",
  ui_story_5061_50611102_2_dialog_content = "I am ready.",
  ui_story_5061_50611102_3_dialog_content = "There is nothing to fear anymore.",
  ui_story_5061_50611102_4_dialog_content = "—!",
  ui_story_5061_50611102_5_dialog_content = "Do it, PlayerName!",
  ui_story_5061_50611102_6_option_content = "Force Boost",
  ui_story_5061_50611102_7_dialog_content = "(...!)",
  ui_story_5061_50611102_8_dialog_content = "(I've never felt anything like this before...)",
  ui_story_5061_50611102_9_dialog_content = "(My consciousness... It keeps flying forward...)",
  ui_story_5061_50611102_10_dialog_content = "(In the real world, all of this is happening within a single moment, but it feels as though my mind's been floating endlessly through a sea of time—)",
  ui_story_5061_50611201_1_dialog_content = "<color=#e8d9bb>█████ years ago, the No. ███ Spark Power Supply Facility.</color>",
  ui_story_5061_50611201_2_dialog_content = "The auxiliary lens deviated for the 4682nd time; the focal length needs recalibration.",
  ui_story_5061_50611201_3_dialog_content = "...",
  ui_story_5061_50611201_4_dialog_content = "Calibration failed. Reason: Irreparable damage to auxiliary lens support No. 44.",
  ui_story_5061_50611201_5_dialog_content = "Solution: Replace it with backup support No. 863.",
  ui_story_5061_50611201_6_dialog_content = "... Damage components replaced. Remaining inventory: 3264 units.",
  ui_story_5061_50611201_7_dialog_content = "Inspection completed; no anomalies found. Today's routine maintenance completed too.",
  ui_story_5061_50611201_8_dialog_content = "<color=#e8d9bb>No. 33 is assigned to maintain various devices within the small facility she is in, especially the Lumina Concentrator.</color>",
  ui_story_5061_50611201_9_dialog_content = "<color=#e8d9bb>Ever since her awakening within the facility, she has been diligently engaged in maintenance work, faithfully executing her given mission.</color>",
  ui_story_5061_50611201_10_dialog_content = "The Lumina Conduit has encountered a blockage for the 78,643rd time and requires clearance.",
  ui_story_5061_50611201_11_dialog_content = "... Clearance attempt failed. Reason: Irreparable damage to conduit 65 interface pipeline.",
  ui_story_5061_50611201_12_dialog_content = "Solution: Replace it with spare pipeline 264; Remaining stock: 0 units.",
  ui_story_5061_50611201_13_dialog_content = "Search for alternative pipelines for use. Pipeline 195, inventory: 0 units; Pipeline 236, inventory: 0 units.",
  ui_story_5061_50611201_14_dialog_content = "No available replacement pipelines; Searching for in-use pipelines suitable for substitution...",
  ui_story_5061_50611201_15_dialog_content = "Found a suitable pipeline at branch interface 80, with a degradation rate of 39%. Preparing for removal and replacement into the interface 65.",
  ui_story_5061_50611201_16_dialog_content = "... Damaged component replaced.",
  ui_story_5061_50611201_17_dialog_content = "System operates normally, power output: 60%.",
  ui_story_5061_50611201_18_dialog_content = "...",
  ui_story_5061_50611201_19_dialog_content = "(... To replace components of the Lumina Concentrator, the surrounding devices were all dismantled...)",
  ui_story_5061_50611201_20_dialog_content = "<color=#e8d9bb>But No. 33 is not just a machine; she is an Aurorian with her body and organs significantly modified.</color>",
  ui_story_5061_50611201_21_dialog_content = "<color=#e8d9bb>As time passed, she too, would experience loneliness, growing weary of the unchanging life within the underground facility.</color>",
  ui_story_5061_50611201_22_dialog_content = "<color=#e8d9bb>And then, she began to question the purpose of her own mission.</color>",
  ui_story_5061_50611201_23_dialog_content = "... Due to the removal of backup power sources, the heating system has been inactive for 436 days.",
  ui_story_5061_50611201_24_dialog_content = "(It must be quite cold now... but I can no longer feel it...)",
  ui_story_5061_50611201_25_dialog_content = "(... Is everything I've done really meaningful?)",
  ui_story_5061_50611201_26_dialog_content = "(It's been so many years, and no one has ever come here or knows what I've been doing.)",
  ui_story_5061_50611201_27_dialog_content = "(Is there still a need for my mission to continue?)",
  ui_story_5061_50611201_28_dialog_content = "Search for alternative data storage modules that can replace the current one in use.",
  ui_story_5061_50611201_29_dialog_content = "No unused storage modules. Search for replaceable modules in active use...",
  ui_story_5061_50611201_30_dialog_content = "No. 33's bio-maintenance device, head, Storage Module 2, with a degradation rate of 32%.",
  ui_story_5061_50611201_31_dialog_content = "(No. 33... Eh?)",
  ui_story_5061_50611201_32_dialog_content = "(My... head? My... storage module?)",
  ui_story_5061_50611201_33_dialog_content = "...",
  ui_story_5061_50611201_34_dialog_content = "(Well, at this point, what's there to regret?)",
  ui_story_5061_50611201_35_dialog_content = "(... I've already removed many parts before anyway. My senses are no longer like those of a living Aurorian...)",
  ui_story_5061_50611201_36_dialog_content = "... Damaged components replaced. System operates normally, power output: 19%.",
  ui_story_5061_50611201_37_dialog_content = "(Despite the low power output, there have been no disasters or accidents.)",
  ui_story_5061_50611201_38_dialog_content = "(Apart from here, there are numerous other facilities in operation.)",
  ui_story_5061_50611201_39_dialog_content = "(With me or without me, it doesn't make much difference.)",
  ui_story_5061_50611201_40_dialog_content = "(... Does this place... still serve a purpose?)",
  ui_story_5061_50611201_41_dialog_content = "<color=#e8d9bb>As her life-sustaining components are gradually dismantled, No. 33 must enter extended hibernation periods to preserve her survival functions.</color>",
  ui_story_5061_50611201_42_dialog_content = "<color=#e8d9bb>She would wake up again in several years; then the next time would be more than a decade later, and then several decades later...</color>",
  ui_story_5061_50611201_43_dialog_content = "<color=#e8d9bb>100 years ago, the No. ███ Spark Power Supply Facility.</color>",
  ui_story_5061_50611201_44_dialog_content = "<color=#e8d9bb><size=45>Rumble—</size></color>",
  ui_story_5061_50611201_45_dialog_content = "(What... What's happening!)",
  ui_story_5061_50611201_46_dialog_content = "(Ugh... Waking up from hibernation, my head hurts... Emergency diagnostics!)",
  ui_story_5061_50611201_47_dialog_content = "(The energy reservoir suffered irreparable damage; high-purity Lumina is dispersing, causing an <color=#FFB400>energy explosion</color> on the surface;)",
  ui_story_5061_50611201_48_dialog_content = "(Why, of all components, is the energy reservoir? It's the most robust part of the concentrator... how could it be damaged...)",
  ui_story_5061_50611201_49_dialog_content = "(... Oh, right... because it's been such a long time... enough for everything to deteriorate...)",
  ui_story_5061_50611201_50_dialog_content = "(... Just how many years have passed? I can't recall with some of the storage modules gone...)",
  ui_story_5061_50611201_51_dialog_content = "Roaaar—",
  ui_story_5061_50611201_52_dialog_content = "(Eclipsites are here?... Right, the defense systems have failed long ago..)",
  ui_story_5061_50611201_53_dialog_content = "(... Everything here... is damaged...)",
  ui_story_5061_50611201_54_dialog_content = "(Ahhhh... at last... is everything finally coming to an end...)",
  ui_story_5061_50611201_55_dialog_content = "(In the very last moments, no one is still aware of all I've done over the years...)",
  ui_story_5061_50611201_56_dialog_content = "(I've long accepted my fate of collapsing along with this place...)",
  ui_story_5061_50611201_57_dialog_content = "(Yet no one knows of my existence, no one is aware of the contributions I've made...)",
  ui_story_5061_50611201_58_dialog_content = "(Anyone will do... at the very least, come... and cast a glance upon me...)",
  ui_story_5061_50611201_59_dialog_content = "(Anyone...)",
  ui_story_5061_50611201_60_dialog_content = "Where am I...?",
  ui_story_5061_50611201_61_dialog_content = "!",
  ui_story_5061_50611201_62_dialog_content = "Hmm? Are you... an Aurorian?",
  ui_story_5061_50611201_63_dialog_content = "—",
  ui_story_5061_50611201_64_dialog_content = "(My Echo Template can no longer support me in making any sounds. So I can only reach out my hand instinctively...)",
  ui_story_5061_50611201_65_dialog_content = "(I reach out to the one who saved me from the endless loneliness—Miss Alina.)",
  ui_story_5061_50611201_66_dialog_content = "(I use a \"part\" of Miss Alina to repair my Echo Template, enabling me to make sounds..)",
  ui_story_5061_50611201_67_dialog_content = "(I recount my mission to her, and she tells me about what has happened on the surface.)",
  ui_story_5061_50611201_68_dialog_content = "(The energy explosion triggered by the malfunction of the Lumina Concentrator is referred to as the <color=#FFB400>Aurorastorm</color> by those on the outside.)",
  ui_story_5061_50611201_69_dialog_content = "The abnormal Lumina produced by the Aurorastorm attracted a large number of Eclipsites.",
  ui_story_5061_50611201_70_dialog_content = "(The facility's deterioration... results in abnormalities in the external Lumina, Eclipsites running rampant, and endangering the survival of Aurorians on the surface.)",
  ui_story_5061_50611201_71_dialog_content = "(I've always thought my mission was to keep the devices operational.)",
  ui_story_5061_50611201_72_dialog_content = "(Yet, actually, is my true purpose to maintain the environment for the Aurorians' survival?)",
  ui_story_5061_50611201_73_dialog_content = "I'm sorry, but I cannot leave this place. Disconnecting may result in even more severe facility instability.",
  ui_story_5061_50611201_74_dialog_content = "Even though the condition of the facility doesn't concern me anymore, I don't want the world outside to endure even more dreadful disasters than it already does.",
  ui_story_5061_50611201_75_dialog_content = "Is there really no other way?",
  ui_story_5061_50611201_76_dialog_content = "... With the equipment here, I can concentrate the Lumina that erupts here onto you, enabling you to unleash this energy on the Eclipsites outside...",
  ui_story_5061_50611201_77_dialog_content = "This way, you can repel the Eclipsite swarm while stopping the Aurorastorm from expanding.",
  ui_story_5061_50611201_78_dialog_content = "But the body of an Aurorian cannot withstand such a vast amount of energy, meaning you would likely disintegrate within a few minutes.",
  ui_story_5061_50611201_79_dialog_content = "(The sole light I've longed for throughout this extended period, am I really going to send it away with my own hands...)",
  ui_story_5061_50611201_80_dialog_content = "... It's fine. We have no other options left.",
  ui_story_5061_50611201_81_dialog_content = "(Please, I'm begging you, don't sacrifice yourself. You are the light I've been waiting so painstakingly to see.)",
  ui_story_5061_50611201_82_dialog_content = "Have you really thought it through?",
  ui_story_5061_50611201_83_dialog_content = "You've protected this place for so long... But now it's time for one of us to protect you.",
  ui_story_5061_50611201_84_dialog_content = "Not only that... But I also want to protect our world for my sister's sake.",
  ui_story_5061_50611201_85_dialog_content = "(No... I don't want to lose you!)",
  ui_story_5061_50611201_86_dialog_content = "I admire your courage. Let us begin...",
  ui_story_5061_50611201_87_dialog_content = "These must be... No. 33's memories!",
  ui_story_5061_50611201_88_dialog_content = "Is it working, PlayerName?",
  ui_story_5061_50611201_89_dialog_content = "It is! Her memories are in the process of recovering!",
  ui_story_5061_50611201_90_dialog_content = "Yes, I remember it now. My mission isn't just to guard this place...",
  ui_story_5061_50611201_91_dialog_content = "And also, to guard the world outside? Alina—",
  ui_story_5061_50611201_92_dialog_content = "Error in Echo Template!",
  ui_story_5061_50611201_93_dialog_content = "So why isn't she getting better?",
  ui_story_5061_50611201_94_dialog_content = "I need to use my powers one more time! This time, I'm sure I can reach the core of her consciousness!",
  ui_story_5061_50611201_95_dialog_content = "Forcing the memory module shutdown...",
  ui_story_5061_50611201_96_dialog_content = "Don't! No! I don't want to forget her!",
  ui_story_5061_50611201_97_dialog_content = "<size=45>Save me! SAVE ME! AHHHHH!</size>",
  ui_story_5061_50611202_1_dialog_content = "Ughhhhh...",
  ui_story_5061_50611202_2_dialog_content = "She stopped!",
  ui_story_5061_50611202_3_dialog_content = "You have to help her, PlayerName!",
  ui_story_5061_50611202_4_option_content = "Force Boost",
  ui_story_5061_50611202_5_dialog_content = "<color=#e8d9bb>In the unfathomable sea of consciousness, a frail figure curls up.</color>",
  ui_story_5061_50611202_6_dialog_content = "My... my mission, my mission is...",
  ui_story_5061_50611202_7_dialog_content = "The Lumina concentrator has been scrapped! Now all I need to do is shut it off and close this place down.",
  ui_story_5061_50611202_8_dialog_content = "I know it's been hard for you all these years, but your mission is finally complete.",
  ui_story_5061_50611202_9_dialog_content = "...!",
  ui_story_5061_50611202_10_dialog_content = "I'm sorry it took so long for us to find you. You must have been so lonely all this time.",
  ui_story_5061_50611202_11_dialog_content = "Why! Why are you only coming to me now?",
  ui_story_5061_50611202_12_dialog_content = "Lumina has been clogged for so long, the relics have been damaged for so long, and I've been in error for so long...",
  ui_story_5061_50611202_13_dialog_content = "I have already decided to give up...",
  ui_story_5061_50611202_14_dialog_content = "But you never gave up, did you? And for that, we'll always be grateful.",
  ui_story_5061_50611202_15_dialog_content = "...",
  ui_story_5061_50611202_16_dialog_content = "Northland has been at peace for so many years, all because you never gave up.",
  ui_story_5061_50611202_17_dialog_content = "The places that weren't under the protection of these ruins were overrun by Eclipsites in no time at all.",
  ui_story_5061_50611202_18_dialog_content = "But the people of Northland have lived happy, peaceful lives for a very long time... And it's all thanks to you.",
  ui_story_5061_50611202_19_dialog_content = "... Really, because of me?",
  ui_story_5061_50611202_20_dialog_content = "My mission... carries meaning?",
  ui_story_5061_50611202_21_dialog_content = "Of course it does! Your mission affected all of Northland, and every single Aurorian living here!",
  ui_story_5061_50611202_22_dialog_content = "Reaching the very end was never the purpose of your mission... The real meaning lies in every single moment of peace you brought for the people of this kingdom.",
  ui_story_5061_50611202_23_dialog_content = "So thank you... Thank you for everything you've done for us.",
  ui_story_5061_50611202_24_dialog_content = "... Thank you.",
  ui_story_5061_50611202_25_dialog_content = "... I remember, once... someone found me like this too...",
  ui_story_5061_50611202_26_dialog_content = "... Thanked me for my effort and even became my companion.",
  ui_story_5061_50611202_27_dialog_content = "And there are plenty of other people who would love to be friends with you too! You don't have to shoulder this burden alone anymore!",
  ui_story_5061_50611202_28_dialog_content = "Everyone here is willing to fight by your side!",
  ui_story_5061_50611202_29_dialog_content = "... But I... After exiting the combat, all connection devices have stopped functioning.",
  ui_story_5061_50611202_30_dialog_content = "... As of now, I'm merely senseless junk of metal.",
  ui_story_5061_50611202_31_dialog_content = "... I'm of no use to you.",
  ui_story_5061_50611202_32_dialog_content = "That's not true, at all. Your heart, your words, your mind... All of those things give us strength, and help make the world a better place.",
  ui_story_5061_50611202_33_dialog_content = "Heart? Mind? You mean... you want my storage unit? Internal or external ones?",
  ui_story_5061_50611202_34_dialog_content = "I, uh... I guess it doesn't make a difference, really! Hey, could you tell me something? Was Northland a warm place in the past?",
  ui_story_5061_50611202_35_dialog_content = "It was warm.",
  ui_story_5061_50611202_36_dialog_content = "Why, though?",
  ui_story_5061_50611202_37_dialog_content = "Because of the different positions of the twilight circle, in the past of this world, there were no such things as eternal days and eternal nights.",
  ui_story_5061_50611202_38_dialog_content = "I see, so Antony was right all along! Thanks a bunch, No. 33! You've just given the world a very important answer about its past!",
  ui_story_5061_50611202_39_dialog_content = "However, I don't know why it's like this, and I can't provide you with the actual answers.",
  ui_story_5061_50611202_40_dialog_content = "That's okay too! Discovering the truth is what our journey is all about. It's something every living Aurorian knows, in some way or another.",
  ui_story_5061_50611202_41_dialog_content = "I see.",
  ui_story_5061_50611202_42_dialog_content = "Say... Do you want to come along with us?",
  ui_story_5061_50611202_43_dialog_content = "Me?",
  ui_story_5061_50611202_44_dialog_content = "Sure! After all, you're part of our world too. Don't you want to experience it for yourself?",
  ui_story_5061_50611202_45_dialog_content = "Come on! The first step's always the hardest, but you'll be fine!",
  ui_story_5061_50611202_46_dialog_content = "... But... my connection devices... I've already lost the ability to receive external signals. I...",
  ui_story_5061_50611202_47_dialog_content = "Just take things one step at a time, and I promise you won't fall.",
  ui_story_5061_50611202_48_dialog_content = "They don't call me the Navigator for no reason, you know! I'll be your eyes, so just keep your head up!",
  ui_story_5061_50611202_49_dialog_content = "This is...",
  ui_story_5061_50611202_50_dialog_content = "An improvised and messy transmitter... configured to specifically match my channel...",
  ui_story_5061_50611202_51_dialog_content = "Ready? Three, two, one...",
  ui_story_5061_50611202_52_dialog_content = "Welcome to the outside world!",
  ui_story_5061_50611202_53_dialog_content = "Sorry we didn't have a chance to properly introduce ourselves earlier.",
  ui_story_5061_50611202_54_dialog_content = "This is Master Novio, a Northland mountain spirit. His shield protected our Lumina from being absorbed just now.",
  ui_story_5061_50611202_55_dialog_content = "That was how PlayerName managed to use his powers on No. 33 without being counterattacked.",
  ui_story_5061_50611202_56_dialog_content = "A pleasure to meet you, Miss Zarya.",
  ui_story_5061_50611202_57_dialog_content = "For the sake of Northland, as well as the future of all Aurorians, I must ask that we keep this incident a secret.",
  ui_story_5061_50611202_58_dialog_content = "While today's events were incredibly significant, we cannot allow the other forces to learn of what has transpired here. Given the current state of things, we have no choice but to allow a certain degree of outside investigation into this place.",
  ui_story_5061_50611202_59_dialog_content = "Nevertheless, I humbly implore that you keep the connection between these ruins and the Spark a well-guarded secret.",
  ui_story_5061_50611202_60_dialog_content = "While the Eclipsite scourge is an ever-present issue for Her Majesty... It is far from her most pressing concern.",
  ui_story_5061_50611202_61_dialog_content = "Aurorians, and their destructive drive for ever-greater power... This is what worries Queen Bethlehem the most.",
  ui_story_5061_50611202_62_dialog_content = "... Understood. The world is still not ready for a discovery like this.",
  ui_story_5061_50611202_63_dialog_content = "... Very well, Master Novio.",
  ui_story_5061_50611202_64_dialog_content = "Thank you all for your cooperation. If you will excuse me, I must be going now...",
  ui_story_5061_50611202_65_dialog_content = "<size=45>Wait!</size>",
  ui_story_5061_50611202_66_dialog_content = "Hmm? Is... Something the matter, Miss Zarya?",
  ui_story_5061_50611202_67_dialog_content = "I-I'm sorry, I didn't mean to shout like that...",
  ui_story_5061_50611202_68_dialog_content = "I... I just wanted to know... What became of my sister in the end...",
  ui_story_5061_50611202_69_dialog_content = "Her name was Alina. A hundred years ago, she...",
  ui_story_5061_50611202_70_dialog_content = "... was the captain of the Spring Patrollers, who were present during the Aurorastorm incident. Is that correct?",
  ui_story_5061_50611202_71_dialog_content = "Y-You still remember?!",
  ui_story_5061_50611202_72_dialog_content = "Your knowledge appears to be slightly outdated, Miss Zarya.",
  ui_story_5061_50611202_73_dialog_content = "Huh?",
  ui_story_5061_50611202_74_dialog_content = "Now, please let me... No, please allow me to convey Miss Alina's \"ending\" to you.",
  ui_story_5061_50611202_75_dialog_content = "... You!",
  ui_story_5061_50611202_76_dialog_content = "No need to worry. PlayerName has already assisted me in rebooting my Echo Template to recover my memories. But he hasn't awakened from the huge exhaustion.",
  ui_story_5061_50611202_77_dialog_content = "The present me will no longer engage in uncontrollable actions.",
  ui_story_5061_50611202_78_dialog_content = "... O-Okay, please tell me what happened to my sister.",
  ui_story_5061_50611202_79_dialog_content = "That day, just when Miss Alina decided to sacrifice herself...",
  ui_story_5061_50611202_80_dialog_content = "Alina! Are you out there?!",
  ui_story_5061_50611202_81_dialog_content = "That sounds like Zarya! But how did she find me here?!",
  ui_story_5061_50611202_82_dialog_content = "There is a deviation in the concentrator's automatic calibration!",
  ui_story_5061_50611202_83_dialog_content = "It's attracted by a more powerful standby vessel!",
  ui_story_5061_50611202_84_dialog_content = "(If I choose an individual with higher talent and survival rates to complete the protocol... they will all be able to survive!)",
  ui_story_5061_50611202_85_dialog_content = "Calculation completed! Execute the optimal plan!",
  ui_story_5061_50611202_86_dialog_content = "What should I do now?!",
  ui_story_5061_50611202_87_dialog_content = "Run! The farther, the better! This place is about to be completely destroyed!",
  ui_story_5061_50611202_88_dialog_content = "But what will happen to you and Zarya?!",
  ui_story_5061_50611202_89_dialog_content = "—Miss Zarya wants you to survive, and so do I.",
  ui_story_5061_50611202_90_dialog_content = "Then, in one fell swoop, you unleashed all your power, annihilating all the Eclipsites present.",
  ui_story_5061_50611202_91_dialog_content = "As a side effect of the energy, it sealed you and the entire ruins in ice.",
  ui_story_5061_50611202_92_dialog_content = "The reason you were able to access my memories through the ruins' Lumina just now is because the ruins have already acknowledged you as part of it.",
  ui_story_5061_50611202_93_dialog_content = "Does that mean my sister... Managed to escape?",
  ui_story_5061_50611202_94_dialog_content = "Yes. Soon afterward, Lady Alina returned to the safety of Northland along with her injured compatriots.",
  ui_story_5061_50611202_95_dialog_content = "It was then that she reported the existence of No. 33... Or rather, the Spirit of the Aurora.",
  ui_story_5061_50611202_96_dialog_content = "... So she survived, after all! My sister made it out alive!",
  ui_story_5061_50611202_97_dialog_content = "Wait... If I became the new vessel, and Alina survived because of it...",
  ui_story_5061_50611202_98_dialog_content = "Does that mean... I protected her?",
  ui_story_5061_50611202_99_dialog_content = "It would appear so. Lady Alina was devastated by the loss of her younger sister and, much like yourself, came to this very place to search for you.",
  ui_story_5061_50611202_100_dialog_content = "Unfortunately, the ice covering the mountain was even denser at the time, and No. 33's dormant state prevented her from sending or receiving signals. As a result, our search efforts were in vain.",
  ui_story_5061_50611202_101_dialog_content = "Alina... I'm so sorry. I can't imagine how much you must have suffered...",
  ui_story_5061_50611202_102_dialog_content = "Nevertheless, Lady Alina soon found the strength to resume her duties.",
  ui_story_5061_50611202_103_dialog_content = "!",
  ui_story_5061_50611202_104_dialog_content = "When I said that your knowledge was slightly outdated, it wasn't merely because your sister managed to survive...",
  ui_story_5061_50611202_105_dialog_content = "But because Lady Alina went on to become a <color=#FFB400>Guardian of the Northland Court</color>. She served faithfully and admirably for many years, and passed away peacefully at the venerable age of eighty-three.",
  ui_story_5061_50611202_106_dialog_content = "A royal court guardian... That was her dream!",
  ui_story_5061_50611202_107_dialog_content = "*sobbing* I'm... I'm so happy... My sister was able to realize her dream!",
  ui_story_5061_50611202_108_dialog_content = "The day of her promotion, Lady Alina had these words to say:",
  ui_story_5061_50611202_109_dialog_content = "Whew! Looks like I'm finally as strong as Zarya always thought I was!",
  ui_story_5061_50611202_110_dialog_content = "Don't worry, Alina... I'll make sure to live well for the both of us!",
  ui_story_5061_50611202_111_dialog_content = "I protected you... Does that make me strong too? Boo-hoo...",
  ui_story_5061_50611202_112_dialog_content = "I... I promise to live well for the both of us too...",
  ui_story_5061_50611202_113_dialog_content = "Thank you, Alina... My sweet, sweet sister...",
  ui_story_5061_50611202_114_dialog_content = "<size=45>...Waaaaaaah!!!</size>",
  ui_story_5061_50611202_115_dialog_content = "(Ugh... My head is spinning...)",
  ui_story_5061_50611202_116_dialog_content = "(Is someone... crying?)",
  ui_story_5061_50611202_117_dialog_content = "Zarya... were you crying just now?",
  ui_story_5061_50611202_118_dialog_content = "...!",
  ui_story_5061_50611202_119_dialog_content = "O-Of course not!",
  ui_story_5061_50611202_120_dialog_content = "But your eyes are all red and puffy...",
  ui_story_5061_50611202_121_dialog_content = "It's just snow! I got snow in my eyes!",
  ui_story_5061_50611202_122_dialog_content = "Pfffff—",
  ui_story_5061_50611202_123_dialog_content = "And just what are you laughing at, Mr. Antony?!",
  ui_story_5061_50611202_124_dialog_content = "Oh, nothing! Anyway, Master Novio, thank you so much for—",
  ui_story_5061_50611202_125_dialog_content = "Huh? Where'd he go?",
  ui_story_5061_50611202_126_dialog_content = "He was just here a second ago...",
  ui_story_5061_50611301_1_dialog_content = "<color=#e8d9bb>Sometime later...</color>",
  ui_story_5061_50611301_2_dialog_content = "Alright, that should be the last batch of parts.",
  ui_story_5061_50611301_3_dialog_content = "Gathering all of these components was such a challenge. We scoured every inch of the mountain just to get our hands on these!",
  ui_story_5061_50611301_4_dialog_content = "Thankfully, Master Novio has been closely monitoring the ruins dotting our kingdom's landscape. Otherwise, we never would have collected so many usable parts.",
  ui_story_5061_50611301_5_dialog_content = "Despite our best efforts, we are still unable to repair this facility. I am sorry.",
  ui_story_5061_50611301_6_dialog_content = "Why are you apologizing, No. 33? We're not trying to repair the ruins, remember? We just want to shut off the Lumina concentrator.",
  ui_story_5061_50611301_7_dialog_content = "After a close assessment of the concentrator's damage, the Winter Palace has deemed it too dangerous for further use. The most sensible decision right now is to shut it down.",
  ui_story_5061_50611301_8_dialog_content = "Master Novio is adjusting the power supplies of the nearby ruins to compensate for the lack of barrier coverage. The Lumina from these ruins will be redirected as well.",
  ui_story_5061_50611301_9_dialog_content = "At least, that's more or less how I understood his plan. The rest, however, is beyond my comprehension...",
  ui_story_5061_50611301_10_dialog_content = "In any case, the Lumina anomaly should be resolved soon enough.",
  ui_story_5061_50611301_11_dialog_content = "Once the concentrator has been deactivated, the Court can arrange for repairs at a later date.",
  ui_story_5061_50611301_12_dialog_content = "So you think we'll be able to disable the concentrator using these parts?",
  ui_story_5061_50611301_13_dialog_content = "Yes, a direct shutdown might trigger a collapse or explosion. We'll need to wait until the core module is repaired before we shut it down.",
  ui_story_5061_50611301_14_dialog_content = "During the shutdown, long-term accumulated Lumina within the concentrator will be cleared out.",
  ui_story_5061_50611301_15_dialog_content = "This might lead to minor earthquakes and aurora phenomena. Please prepare for the potential impact.",
  ui_story_5061_50611301_16_dialog_content = "Very well, I'll initiate the shutdown process now.",
  ui_story_5061_50611301_17_dialog_content = "Once it's deactivated, you won't need to stay connected to it, right?",
  ui_story_5061_50611301_18_dialog_content = "Yes. I won't need a connection, at least until the repair work starts.",
  ui_story_5061_50611301_19_dialog_content = "Then... Do you wanna come take a look at my Colossus?",
  ui_story_5061_50611301_20_dialog_content = "You said you wanted to see how other Aurorians live in the world, didn't you?",
  ui_story_5061_50611301_21_dialog_content = "?",
  ui_story_5061_50611301_22_dialog_content = "I...",
  ui_story_5061_50611301_23_dialog_content = "I've experienced an emotion that has rarely been recorded before. Could this be... hesitation?",
  ui_story_5061_50611301_24_dialog_content = "Maybe the excitement is just getting to your head? Hmm, I wonder how you would describe that...",
  ui_story_5061_50611301_25_dialog_content = "I got it! Your storage device is being temporarily overloaded!",
  ui_story_5061_50611301_26_dialog_content = "Look, it's starting!",
  ui_story_5061_50611301_27_dialog_content = "<color=#e8d9bb>Rumble—Rumble—Rumble—</color>",
  ui_story_5061_50611301_28_dialog_content = "<color=#e8d9bb>The Lumina, long clogged, is finally released now, returning to the energy cycle of Astra.</color>",
  ui_story_5061_50611301_29_dialog_content = "<color=#e8d9bb>Once again, the dazzling aurora appears in the skies at the border.</color>",
  ui_story_5061_50611301_30_dialog_content = "You really have to see it to believe it...",
  ui_story_5061_50611301_31_dialog_content = "This aurora is like something out of a fairy tale. I had no idea something like this could be created by a machine.",
  ui_story_5061_50611301_32_dialog_content = "On the continent of Astra, there are many energy facilities like this.",
  ui_story_5061_50611301_33_dialog_content = "Their power connects straight to the Earth's core, symbolizing the incredible might of ancient civilizations in reshaping the world.",
  ui_story_5061_50611301_34_dialog_content = "But an aurora like this can only be seen here, right?",
  ui_story_5061_50611301_35_dialog_content = "That's right. It's only visible here because of our position near the twilight circle, where light and darkness meet.",
  ui_story_5061_50611301_36_dialog_content = "The skies are extremely clear in this area, and the collision of Lumina particles is extremely noticeable here!",
  ui_story_5061_50611301_37_dialog_content = "I've dreamt about this moment more times than I can count... But nothing compares to seeing it with my own two eyes.",
  ui_story_5061_50611301_38_dialog_content = "Antony...",
  ui_story_5061_50611301_39_dialog_content = "(There must be so many others like him in the world: people who explore the unknown with only their intuition and self-taught knowledge to guide them...)",
  ui_story_5061_50611301_40_dialog_content = "(It makes me happy knowing that people like him can uncover the world's secrets and realize their dreams too.)",
  ui_story_5061_50611301_41_dialog_content = "I finally understand why you're constantly searching for answers to the most difficult questions in life, Antony.",
  ui_story_5061_50611301_42_dialog_content = "The way my heart is racing right now...",
  ui_story_5061_50611301_43_dialog_content = "It makes me want to explore even deeper questions about our world.",
  ui_story_5061_50611301_44_dialog_content = "... For example: What kind of world do we truly live in?",
  ui_story_5061_50611301_45_dialog_content = "... Where did we come from?",
  ui_story_5061_50611301_46_dialog_content = "... Where are they headed towards?"
}
return config
